import{M as s,r as t,m as c}from"./courses-Dys-d8iQ.js";function u(e){const a=`manifest-${e.number}`;return{schemaVersion:2,revision:1,id:a,courseId:"manifest",locale:"es",title:e.title,goal:e.goal,minutes:{learning:5,suggestedAction:5,review:2},direction:{hook:e.hook,reason:{id:`${a}-reason`,label:e.reason,kind:"text",maxLength:160,optional:!0,suggestions:["Mi meta; menos repeticiones","Actuar antes de seguir preparando","Buscar apoyo antes de volver a intentar"]},why:{id:`${a}-purpose`,label:"¿Qué aporta este paso a tu semana?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:e.paragraphs,example:e.example},move:{invitation:"Conserva tu meta. Elige una acción que te sirva.",instructions:e.instructions,prompts:[],suggestions:{action:e.action,minimum:e.minimum,cue:e.cue,place:e.place,fallback:e.fallback,observation:e.observation,minutes:[5,2,10],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}]},suggested:{action:e.action[0],minimum:e.minimum[0],minutes:5,cueHint:e.cue[0],placeHint:e.place[0],obstacleHint:e.obstacle,fallbackHint:e.fallback[0],observationHint:e.observation[0]},accessibleAlternative:"Escribe, dicta o describe el ritual; no necesitas materiales ni imaginar escenas con claridad.",stopRule:e.stopRule},result:{question:"¿Hiciste el mínimo que habías elegido?",observationPrompt:"¿Qué hiciste en concreto, aparte de practicar el ritual?"},judgment:{primary:{id:`${a}-decision`,scenario:e.scenario,question:e.question,options:e.options.map(r=>({id:`${a}-${r.key}`,text:r.text,feedback:r.feedback})),bestOptionId:`${a}-${e.best}`}},carry:{takeaway:e.takeaway,followUp:{questionId:`${a}-return`,question:e.review,observationPrompt:"¿Qué ocurrió cuando planeabas actuar, incluida cualquier respuesta de otras personas?",adjustmentPrompt:"¿Qué cambio harías para la próxima oportunidad?"}},goDeeper:{sections:e.deeper,sourceIds:e.sources}}}const l={"manifest-T01":{finding:"24 efectos independientes de 21 artículos, 15,907 participantes: combinar contraste mental y planes de «si pasa esto, haré aquello» favoreció alcanzar metas en promedio, g = .336 [.229, .443]. El ajuste por sesgo estimó .242 [.143, .342].",limitation:"Los efectos variaron y hubo indicios de sesgo de publicación. No garantiza el éxito, no demuestra que el malestar sea necesario ni evalúa esta biblioteca y sus adaptaciones de rituales."},"manifest-T02":{finding:"Un metaanálisis de referencia reunió 94 pruebas independientes con 8,461 participantes. Los planes específicos de «si pasa esto, haré aquello» mostraron un beneficio promedio para alcanzar metas, d = .65 [.60, .70].",limitation:"Evidencia antigua y diversa, sin registro previo uniforme. Un plan no elimina las barreras externas ni el esfuerzo, y tampoco garantiza la decisión de otra persona."},"manifest-T03":{finding:"138 experimentos aleatorizados, con 19,951 participantes en total: fomentar el seguimiento del progreso mejoró el logro de metas en promedio, d = .40 [.32, .48]. Anotar el progreso se asoció con efectos mayores entre estudios.",limitation:"Variaban las intervenciones y las metas. Las comparaciones entre estudios no prueban que cada forma de anotar funcione. Revisar al día siguiente es una adaptación de ODA, no un calendario óptimo establecido."},"manifest-T04":{finding:"94 estudios, 123 efectos, 5,685 participantes: la simulación mental favoreció la conducta posterior en promedio, g = .49 [.37, .62]. La comparación general no estableció diferencias entre tipos de simulación.",limitation:"Principalmente estudiantes, con tareas y simulaciones diversas. Varios subgrupos tenían pocos efectos. No se establecieron un orden fiable entre tipos, la atracción de sucesos externos ni una ventaja especial al acostarse."},"manifest-T05":{finding:"Cuatro experimentos encontraron que algunas fantasías sobre futuros positivos idealizados redujeron la energía inmediata, con algunas diferencias en logros posteriores. Esto distingue fantasear por placer de prepararse para el esfuerzo.",limitation:"Experimentos breves, principalmente con estudiantes. No todo optimismo ni imaginación hace daño. No se midió la supuesta señal cerebral de que una meta ya está cumplida."},"manifest-T06":{finding:"Dos experimentos encontraron que repetir una frase muy positiva sobre uno mismo podía empeorar el ánimo de participantes con baja autoestima; los beneficios para quienes tenían alta autoestima fueron limitados.",limitation:"Frases, muestras y resultados de corto plazo concretos. Esto no demuestra que todo mensaje de ánimo haga daño ni evalúa cada práctica de afirmaciones. Una frase creíble que invite a actuar es una adaptación de ODA."},"manifest-T07":{finding:"144 pruebas experimentales evaluaron afirmar valores, cualidades o relaciones importantes junto con información de salud. Los efectos sobre aceptación e intenciones fueron pequeños; 46 pruebas de conducta, con 2,715 participantes, dieron d = .32 [.19, .44].",limitation:"La autoafirmación basada en valores difiere de repetir como cierto un resultado deseado. Los hallazgos sobre mensajes de salud no establecen que repetir frases atraiga empleos, dinero o relaciones."},"manifest-T08":{finding:"29 estudios, 2,909 participantes: escribir sobre el mejor futuro posible después de trabajar para alcanzarlo mejoró el bienestar, el optimismo y las emociones positivas en promedio frente a los grupos de control.",limitation:"Principalmente estudiantes jóvenes; ningún estudio cumplió todos los criterios de calidad. Los resultados sobre ánimo y optimismo no prueban el logro de metas externas ni la eficacia de escribir el futuro en presente."},"manifest-T09":{finding:"Los estudios aleatorizados de gratitud mostraron beneficios promedio pequeños para el bienestar frente a algunos controles. Para el bienestar, la gratitud no superó otras actividades psicológicas activas; los hallazgos sobre ansiedad fueron inconcluyentes.",limitation:"Los efectos dependen de las actividades de comparación y de la calidad de los estudios. No se establece una frecuencia universal para escribir, la atracción de sucesos externos ni el efecto añadido de agradecer un hecho futuro como si hubiera ocurrido."},"manifest-T10":{finding:"27 estudios, 3,675 participantes: las intervenciones de gratitud tuvieron efectos promedio pequeños al agrupar síntomas de depresión y ansiedad. Los efectos fueron mayores frente a listas de espera que frente a controles activos. El análisis separado de ansiedad tuvo cinco estudios y fue inconcluyente.",limitation:"Los hallazgos modestos sobre síntomas no establecen que la gratitud sea un tratamiento suficiente. Los autores recomiendan intervenciones con mayor respaldo para quienes buscan aliviar la depresión o la ansiedad."},"manifest-T11":{finding:"Una revisión de décadas de investigación sobre metas describe cómo las metas específicas y exigentes pueden favorecer el desempeño. El compromiso, los comentarios recibidos, la capacidad y la complejidad de la tarea influyen en los resultados.",limitation:"Revisión narrativa de una teoría, no una prueba de rituales de manifestación. Las metas requieren estrategias y recursos viables; las tareas nuevas o complejas pueden necesitar metas de aprendizaje en vez de presión por rendir de inmediato."},"manifest-T12":{finding:"146 estudios aleatorizados sobre expresar experiencias o sentimientos encontraron un beneficio promedio pequeño entre distintos resultados, r medio = .075 [.052, .098]. Los efectos variaban según el resultado y el procedimiento.",limitation:"Escribir sobre experiencias reales difiere de contar un hecho deseado como si fuera cierto. Esta revisión no valida cualquier diario, no promete recuperarse de un trauma ni muestra que las historias escritas causen resultados externos."},"manifest-T13":{finding:"Tres muestras de encuestas en línea de Estados Unidos, 1,023 participantes: creer en la manifestación se relacionó con confianza y algunos reportes de riesgo financiero y bancarrota, pero no con ingresos ni educación reportados.",limitation:"Las asociaciones y los resultados reportados por los participantes no establecen causalidad, frecuencia en la población ni eficacia de cada técnica. La confianza no es evidencia objetiva de éxito."},"manifest-T14":{finding:"Un análisis del aprendizaje a partir de organizaciones que sobreviven muestra cómo observar pocos fracasos puede hacer que una práctica sin relación parezca asociada con el éxito.",limitation:"Modelos de organizaciones, no un estudio de la publicación viral aportada por la persona responsable del proyecto. Aplicar este principio de selección a los testimonios de manifestación es una inferencia; no demuestra que alguien mienta al contar su historia."},"manifest-T15":{finding:"Esta revisión de la atención describe cómo lo que seleccionamos depende de las metas actuales, de lo que destaca físicamente y de lo que seleccionamos antes. Una meta puede influir en lo que recibe atención, junto con otros factores.",limitation:"La teoría sobre atención visual no evalúa tableros de visión, afirmaciones, un único filtro de deseos del sistema reticular ni la creación de oportunidades externas. Notar una oportunidad y hacer que exista son afirmaciones distintas."},"manifest-T16":{finding:"351 estudios, 862 efectos: la revisión encontró un efecto promedio de la activación previa sobre la conducta. El subgrupo menor de estudios con registro previo tuvo efectos más pequeños y estadísticamente inconcluyentes, lo que señala incertidumbre sobre su fiabilidad y condiciones.",limitation:"Los estímulos incidentales de los experimentos difieren de los rituales deliberados de manifestación. El pequeño subgrupo con registro previo no refuta toda activación previa; el conjunto tampoco valida repetir frases, umbrales exactos de tiempo ni atracción cósmica."},"manifest-T17":{finding:"Un estudio temprano sobre exámenes favoreció imaginar cómo estudiar frente a imaginar solo una buena calificación; la planificación y la ansiedad ayudaron a explicar las diferencias en notas. El efecto principal del proceso sobre las notas fue marginal; una comparación posterior entre solo proceso y solo resultado fue significativa.",limitation:"El resultado de proceso frente a control no fue significativo en la síntesis posterior de Cole, que no estableció un tipo ganador universal. Un estudio temprano y limitado no demuestra mejoras fiables de notas frente a control ni atracción de sucesos externos."},"manifest-T18":{finding:"Este resumen de un programa de investigación distingue imaginar el proceso y cómo afrontar dificultades de imaginar solo el éxito final. Destaca la planificación y la resolución de problemas.",limitation:"Revisión de un programa de investigación, no un metaanálisis exhaustivo ni prueba de que imaginar el proceso siempre sea mejor. Considérala junto con la síntesis posterior de Cole y un intento real."},"manifest-T19":{finding:"Una revisión de neurociencia describe el sistema reticular activador como parte de circuitos que interactúan y participan en la vigilia y la activación de la corteza cerebral.",limitation:"La neurociencia de la activación no establece que escribir un deseo programe un filtro cerebral que entregue oportunidades, ni que la somnolencia permita alterar sucesos externos con pensamientos. No se evaluó ningún ritual de manifestación."},"manifest-P01":{finding:"Receta de quienes practican el método: escribir una intención en presente tres veces por la mañana, seis por la tarde y nueve por la noche.",limitation:"Guía descriptiva de la práctica, no evidencia controlada de eficacia. Los números, ciclos, afirmaciones sobre la atención y vínculos con Tesla no son hallazgos científicos."},"manifest-P02":{finding:"Receta de quienes practican el método: escribir en un diario un día ideal imaginado, en primera persona y presente, incluir detalles sensoriales y sentimientos, y después releerlo.",limitation:"Describe un ritual. La programación del subconsciente, las vibraciones, las sincronicidades y los resultados personales no son evidencia de investigación controlada."},"manifest-P03":{finding:"Receta de quienes practican el método: elegir metas e imágenes o palabras que las representen, armar un collage físico o digital, dejarlo a la vista y revisarlo con frecuencia.",limitation:"Guía descriptiva, no evidencia de eficacia de los tableros. Esta página no establece la Ley de la Atracción, las anécdotas de éxito ni las explicaciones sobre el sistema reticular activador."},"manifest-P04":{finding:"Receta de quienes practican el método: crear frases breves y específicas en primera persona y presente, y leerlas o repetirlas, a menudo por la mañana y por la noche.",limitation:"Las frases positivas difieren de la autoafirmación basada en valores que estudia la investigación. Esta guía no establece beneficios universales ni efectos sobre resultados externos."},"manifest-P05":{finding:"La guía describe imaginar el resultado deseado con detalles sensoriales, ensayar en primera persona e imaginar el proceso para alcanzar una meta.",limitation:"Orientaciones descriptivas, sin respaldo para garantías ni afirmaciones de atracción. Los hallazgos empíricos sobre simulación deben comprobarse en las fuentes de investigación."},"manifest-P06":{finding:"Receta de quienes practican el método: escribir una afirmación 55 veces seguidas durante cinco días consecutivos mientras se imagina que ya es cierta.",limitation:"Descripción pública; no hace falta comprar la hoja de ejercicios. La cantidad de repeticiones y las explicaciones sobre vibraciones altas no son evidencia establecida de eficacia."},"manifest-P07":{finding:"Receta narrada en primera persona: etiquetar vasos con la situación actual y la deseada, imaginar el cambio, pasar agua del primero al segundo y después beberla.",limitation:"Relato anónimo de la práctica, no evidencia causal verificada. Cambiar de realidad y forzar resultados son afirmaciones sin respaldo. Usa agua potable sin añadidos y vasos limpios."},"manifest-P08":{finding:"Receta de quienes practican el método: escribir un deseo en presente, doblar el papel y dejarlo bajo la almohada, y después repetirlo o imaginarlo mientras se concilia el sueño.",limitation:"Varían las repeticiones y los dobleces. Las afirmaciones sobre el papel, el subconsciente, los cristales, los aceites y la atracción no son evidencia controlada de eficacia."},"manifest-P09":{finding:"Receta de quienes practican el método: relajarse, imaginar que uno se acerca a otra persona, susurrarle al oído una petición deseada tres veces y salir de la escena imaginada.",limitation:"Testimonio personal, no evidencia de telepatía. Una petición imaginada no establece control sobre otra persona ni permite ignorar su consentimiento y sus límites."},"manifest-P10":{finding:"Un relato en primera persona describe un diario de gratitud: anotar cosas que se agradecen junto con los motivos y después releerlas.",limitation:"Relato personal, no investigación sobre una intervención. La historia no establece que la gratitud atraiga sucesos o elimine problemas."},"manifest-P11":{finding:"Un relato en primera persona describe preparar ropa y equipaje como si un empleo deseado ya estuviera confirmado, mientras se imagina el resultado esperado.",limitation:"La autora relata una oferta de alguien que ya conocía. Una anécdota no permite aislar la causa ni confirmar una ley general de atracción."},"manifest-P12":{finding:"El recurso describe imaginar que tu yo futuro escribe a tu yo actual sobre cambios en su vida y le habla con comprensión.",limitation:"Las páginas 6-7 documentan la práctica, no la comunicación desde el futuro ni la eficacia para obtener resultados externos. La fecha y el saludo son opciones de formato."},"manifest-P13":{finding:"Una transcripción de la enseñanza indica mantener un pensamiento deseado durante 17 segundos sin contradecirlo. Incluye una versión de cuatro intervalos que suman 68 segundos.",limitation:"Enseñanza espiritual, no evidencia controlada. Los umbrales exactos, la combustión de pensamientos, la manifestación física y la supuesta equivalencia con horas de trabajo carecen de respaldo."},"manifest-P14":{finding:"Receta narrada en primera persona: poner tarjetas de intenciones o imágenes en una caja, incluir sentimientos deseados y volver a revisar el contenido.",limitation:"Documenta una práctica simbólica. Las explicaciones sobre campos de energía y manifestación son creencias, no hallazgos científicos. Basta con un recipiente que ya tengas."},"manifest-P15":{finding:"El texto original describe relajarse hasta sentir somnolencia, imaginar una escena breve de un deseo cumplido, participar en primera persona y repetir hasta que la acción imaginada se sienta real.",limitation:"La transcripción gratuita documenta la enseñanza de SATS, no su eficacia. Las afirmaciones metafísicas sobre resultados externos y sobre no necesitar actuar no son evidencia científica; protege tu sueño."}},o=[...s,...t].map(e=>({...e,...l[e.id]})),d=[{number:6,technique:"Método 3-6-9",title:"3-6-9: del cuaderno a la solicitud",goal:"Conserva el cuaderno y actúa hacia una meta concreta.",hook:"¿Otra vez «Conseguí el empleo»? Envía una solicitud a esa empresa de la otra página.",reason:"¿El cuaderno te ayuda a postular o te quita tiempo?",paragraphs:["El método 3-6-9 repite una afirmación en presente tres veces por la mañana, seis al mediodía y nueve por la noche. En dos páginas, las empresas deseadas van a la izquierda; «Conseguí el empleo», a la derecha. Sin respaldo: que esas cantidades atraigan ofertas. Un testimonio no separa repeticiones de solicitudes ni muestra intentos fallidos.","Versión ODA: conserva las páginas y el ritmo opcional. Izquierda: empresas concretas y la solicitud, consulta o preparación de hoy. Derecha: una frase creíble sobre ti y un plan «si ocurre esto, haré aquello», con respaldo científico. Actúa hoy; mañana separa lo que hiciste de cualquier respuesta."],example:{title:"Mariana usa ambas páginas",text:"Mariana anota dos empresas de logística a la izquierda y «Preparo solicitudes útiles» a la derecha. Después de almorzar, revisa una vacante y envía un CV adaptado. Su plan dice: «Si falla el portal, guardaré el borrador y contactaré a selección de personal». Un portal falla. Anota que pidió ayuda; ninguna empresa le ha ofrecido empleo."},instructions:["Izquierda: anota una empresa y la solicitud, consulta o preparación de hoy.","Derecha: añade una frase sobre ti y qué harás si surge un obstáculo.","Da ese paso; mañana revisa tu intento y cualquier respuesta de la empresa."],action:["Enviar una solicitud adaptada","Consultar sobre una solicitud enviada"],minimum:["Enviar una solicitud adecuada","Enviar una pregunta de seguimiento"],cue:["Al terminar de almorzar","Después de escribir por la mañana"],place:["En mi escritorio de postulaciones","En el portal de la empresa"],obstacle:"El portal de solicitudes no carga",fallback:["Guardar el borrador y contactar a selección","Usar otra vía disponible para postular"],observation:["El envío o consulta y cualquier respuesta","El paso que completé para postular"],stopRule:"Omite repeticiones que resten tiempo para actuar; pausa solicitudes fuera de tu presupuesto o inadecuadas.",scenario:"Mariana completó las 18 repeticiones y anotó tres empresas. Una vacante adecuada cierra esta noche. Para postular, necesita un párrafo breve sobre su experiencia.",question:"¿Qué debería salir de su próxima sesión con el cuaderno?",options:[{key:"repeat",text:"Mantener las repeticiones y preparar una frase más larga sobre sí misma antes de volver a la solicitud.",feedback:"La frase puede seguir en su ritual, pero alargarla no completa lo que falta en la solicitud. Como el plazo está cerca, usa el cuaderno para recordar que debe escribir ese párrafo."},{key:"submit",text:"Escribir el párrafo, enviar la solicitud y anotar el envío por separado de cualquier respuesta de la empresa.",feedback:"Esto responde a la vacante concreta y su plazo. El envío depende de ella; la respuesta no. Puede conservar el ritual si le gusta y luego revisar qué ocurrió en realidad."},{key:"expand",text:"Ampliar primero la lista de empresas para tener mañana más opciones de empleo entre las cuales elegir.",feedback:"Ampliar la búsqueda puede servir después, pero esta noche hay una vacante adecuada con fecha límite. Alargar la lista retrasaría esa solicitud disponible. Primero termina el párrafo que le falta para enviarla."}],best:"submit",takeaway:"Que el cuaderno te recuerde postular. Separa las acciones de las respuestas.",review:"¿Qué paso intentaste hacia una empresa? ¿Alguna te respondió?",deeper:[{heading:"La receta habitual, con sus dos páginas",paragraphs:["1. Elige un resultado deseado y exprésalo como si ya fuera cierto. 2. Escribe esa afirmación tres veces por la mañana. 3. Repítela seis veces al mediodía. 4. Escríbela nueve veces por la noche. Estas cantidades describen la receta popular; no son una dosis respaldada por estudios. Cada practicante puede repetir el horario durante un período distinto. [manifest-P01]","5. En el ejemplo de dos páginas que aportó la dueña del proyecto, la derecha dice «Conseguí el empleo»; la izquierda enumera empresas donde postuló y quiere trabajar. Ella cuenta que recibió una oferta de una empresa de la lista. Es un relato aportado por la dueña del proyecto, sin verificación independiente mediante un ensayo. Aplicar aquí el sesgo de supervivencia es una inferencia: el éxito visible deja fuera a quienes probaron el ritual sin recibir ofertas. El relato puede ser sincero sin aclarar su causa. [manifest-T14]"]},{heading:"Conserva el ritmo y úsalo para empezar",paragraphs:["La evidencia sobre planificación estudia una situación reconocible vinculada a una respuesta posible. No demuestra que repetir tres, seis o nueve veces influya en una empresa. Conserva la cuenta si la disfrutas y escribe al lado la tarea: una empresa, una vacante adecuada y la acción de hoy. La lista izquierda y las solicitudes ofrecen una vía práctica hacia una oferta; esta anécdota no prueba qué factor causó la suya. [manifest-T02, manifest-T14]","A la derecha, prueba «Preparo solicitudes útiles». Añade «Si falla el portal, guardaré el borrador y contactaré a selección de personal». Revisa el plazo, el acceso y el tiempo disponible. Envía o pregunta hoy y anota qué hiciste. Mañana busca la respuesta de la empresa sin atribuir el silencio a tu falta de fe. Repeticiones, preparación, solicitudes y ofertas van en entradas separadas. Esta propuesta de dos páginas es una adaptación de ODA, no una intervención probada. [manifest-T02]"]}],sources:["manifest-P01","manifest-T02","manifest-T14"]},{number:7,technique:"Escritura de tu futuro",title:"Escribe tu futuro y también lo que requiere",goal:"Usa una escena futura para elegir e intentar una acción.",hook:"¿Escribes tu día perfecto y dejas la entrevista pendiente? Añade el trabajo para llegar ahí.",reason:"¿Qué harás con esta página antes de escribir otra?",paragraphs:["Escribir tu futuro es narrar en un diario lo que deseas como si ocurriera ahora. Elige una escena, describe detalles y emociones y relee. Evidencia mixta: escribir sobre el mejor futuro posible mejoró bienestar y optimismo en promedio; no demostró atraer acontecimientos al escribir en presente. La escritura expresiva estudia experiencias reales, no deseos cumplidos.","Versión ODA: conserva la escena e incluye el trabajo necesario. Nombra tu meta concreta, un obstáculo actual y qué harás si aparece. Subraya una acción para hoy. Mañana compara tu intento con el plan, no con todo lo imaginado. La combinación es una adaptación."],example:{title:"Elena añade el trabajo pendiente",text:"Elena escribe una mañana tranquila en un nuevo puesto y añade la preparación previa para la entrevista. Después de cenar, graba cómo atendería a un cliente difícil. Al escucharse, nota que se apresura y marca una frase para acortar. El empleo sigue siendo hipotético; tiene una grabación real para mejorar mañana."},instructions:["Escribe la escena futura con el trabajo y los recursos que requeriría.","Subraya la acción de hoy; añade «Si aparece este obstáculo, haré…».","Intenta el mínimo que elegiste y mañana revisa qué ocurrió."],action:["Grabar una respuesta de entrevista","Redactar una descripción para mi portafolio"],minimum:["Guardar una respuesta grabada","Guardar una descripción útil"],cue:["Después de recoger la cena","Cuando cierre mi diario"],place:["En la mesa de mi cocina","En el documento de mi portafolio"],obstacle:"No encuentro la primera frase perfecta",fallback:["Empezar con una frase provisional","Pedir un ejemplo concreto"],observation:["La grabación que guardé","El borrador y lo que falta"],stopRule:"Omite escenas que te causen malestar; usa notas de tareas si escribir el futuro no ayuda.",scenario:"Elena describe una entrevista donde se siente segura. La entrevista es mañana y no tiene un ejemplo para una pregunta habitual sobre atención al cliente.",question:"¿Qué cambio vuelve útil esa página esta noche?",options:[{key:"draft",text:"Añadir un ejemplo real con un cliente, ensayar una respuesta y guardar una primera grabación para revisarla mañana.",feedback:"Así conecta la escena con la tarea de mañana. Una respuesta provisional muestra qué mejorar. No asegura el empleo, pero deja una preparación que Elena puede escuchar y ajustar antes de la entrevista."},{key:"feelings",text:"Describir con más detalle cómo se siente esa seguridad antes de decidir qué ejemplo de atención al cliente usar.",feedback:"Explorar emociones puede darle sentido a la escena. Aquí falta una respuesta basada en experiencia real. Describir más la emoción deja ese vacío; conviene elegir un ejemplo y practicar cómo lo contará."},{key:"edit",text:"Pulir toda la entrada del diario para que la entrevista imaginada forme una historia clara y coherente.",feedback:"Una historia coherente es una meta de escritura. La meta inmediata de Elena es preparar una respuesta. Corregir la narración consume su tiempo de esta noche sin producir el ejemplo que necesita."}],best:"draft",takeaway:"Escribe un futuro que quieras y haz hoy una parte del trabajo que requiere.",review:"¿Qué paso escrito llegaste a intentar? ¿Qué sigue pendiente?",deeper:[{heading:"Cómo se escribe este futuro",paragraphs:["1. Elige una situación deseada, como un día de trabajo en el puesto que quieres. 2. Escribe una entrada de diario como si ese día estuviera ocurriendo. 3. Describe detalles cotidianos: dónde estás, qué haces y cómo te sientes. 4. Relee y vuelve al texto si quieres. Algunas versiones añaden gratitud o una sensación de certeza. Son instrucciones de practicantes, no una vía validada para conseguir una oferta. [manifest-P02]","Deja claro qué acontecimientos son imaginados. Puedes narrar una escena cotidiana sin inventar promesas de otra persona. En el ejercicio ODA, añade el trabajo necesario, los recursos disponibles y un obstáculo actual. Elige una tarea de esa página. Usar el teclado o grabar tu voz son opciones de accesibilidad; no afirmamos que todos los formatos tengan idénticos efectos en los estudios. El ritual es opcional. [manifest-P02]"]},{heading:"El futuro imaginado y las experiencias reales son distintos",paragraphs:["Los estudios del mejor futuro posible piden imaginar un buen futuro tras esforzarse por alcanzarlo. Carrillo y colegas encontraron beneficios promedio en bienestar, optimismo y emociones positivas, con limitaciones en la calidad de los estudios. Esto permite expectativas acotadas sobre la escritura reflexiva. No demuestra que narrar en presente haga ocurrir los acontecimientos escritos. La escritura expresiva se ocupa de experiencias o sentimientos reales. Su pequeño beneficio promedio tampoco valida atraer acontecimientos futuros. [manifest-T08, manifest-T12]","ODA conserva la narración y añade una forma de pasar a la acción. Elige una meta concreta que ya forme parte de tu experimento del curso. Nombra qué puede impedir el paso de hoy y escribe una respuesta posible con tus recursos. Guarda cuándo actuar y tu mínimo, inténtalo y revisa mañana. Anota el ensayo de entrevista como preparación, la solicitud como envío y una respuesta solo cuando llegue. Este proceso es una adaptación de diseño; no reproduce ninguna de las dos intervenciones de escritura tal como se probaron."]}],sources:["manifest-P02","manifest-T08","manifest-T12"]},{number:8,technique:"Tablero de visión",title:"Tablero de visión: una imagen, una tarea",goal:"Usa una imagen como señal para una acción posible.",hook:"¿Tablero impecable, proyecto pendiente? Dale a una imagen una tarea para hoy.",reason:"¿Qué imagen refleja tus prioridades y no las de otros?",paragraphs:["Un tablero de visión reúne imágenes y palabras de la vida deseada. Elige fotos, ordénalas, déjalo visible y vuelve a mirarlo. Evidencia mixta: las metas actuales pueden orientar la atención junto con lo llamativo y la experiencia previa. Eso no valida el tablero ni demuestra atraer oportunidades. El sistema reticular activador participa en la vigilia y activación; llamarlo filtro programable de deseos exagera la evidencia.","Versión ODA: conserva una imagen que te importe. Anota su meta concreta y la acción de hoy. Nombra un obstáculo y qué harás si aparece; verla será tu señal. Mañana revisa si cumpliste tu mínimo. Detectar una oportunidad no equivale a crearla."],example:{title:"Nora añade una tarea",text:"El tablero de Nora muestra un escritorio en un estudio de diseño. Escribe «Crear una muestra para mi portafolio». Al verla después de desayunar, abre su proyecto pendiente y redacta una descripción. La imagen emociona menos que imaginarse en el estudio. Guarda la descripción y anota que aún necesita comentarios."},instructions:["Elige una imagen; escribe su meta concreta y la acción útil de hoy.","Úsala como señal y prepara una respuesta a un obstáculo probable.","Intenta la acción; mañana revisa si notaste esa señal al verla."],action:["Escribir una descripción para mi portafolio","Pedir comentarios sobre un proyecto"],minimum:["Guardar una descripción útil del proyecto","Enviar una pregunta para recibir comentarios"],cue:["Al ver el tablero después de desayunar","Al abrir mi carpeta de proyectos"],place:["En mi escritorio de trabajo","En el documento de mi portafolio"],obstacle:"La imagen me lleva a navegar, no a trabajar",fallback:["Abrir el proyecto antes de navegar","Poner un recordatorio junto al archivo"],observation:["Si la imagen me llevó a empezar","La descripción o pregunta que completé"],stopRule:"Usa imágenes o palabras que ya tengas; omite imágenes que te presionen a gastar.",scenario:"Nora ve su tablero cada mañana y luego busca fotos de estudios. A su portafolio le falta la descripción que explicaría un proyecto terminado.",question:"¿Qué cambio le serviría más?",options:[{key:"fresh",text:"Cambiar la foto del estudio por otra más inspiradora para que el tablero vuelva a despertar su interés.",feedback:"Una imagen nueva puede gustarle, pero su registro muestra que navega después de verla. No muestra que falte una aspiración. Cambia lo que debe hacer al encontrarse con esa imagen cada mañana."},{key:"study",text:"Dedicar la próxima mañana a comparar portafolios de estudios para entender qué nivel quiere alcanzar con su trabajo.",feedback:"Comparar puede orientar trabajos futuros. Nora ya tiene un proyecto terminado al que le falta una descripción. Seguir navegando repite el patrón, salvo que responda una pregunta concreta necesaria para escribirla."},{key:"label",text:"Escribir bajo la imagen «Abrir proyecto, redactar descripción» y guardar una descripción antes de buscar más fotos de estudios.",feedback:"Esto conecta la señal existente con la acción pendiente. Mañana Nora puede revisar si vio el texto y guardó la descripción. El tablero por sí solo no garantiza empleo en un estudio."}],best:"label",takeaway:"Dale una tarea a la imagen y úsala como señal. Revisa qué hiciste.",review:"¿Ver la imagen te llevó a hacer lo planeado o a otra cosa?",deeper:[{heading:"Arma tu tablero sin comprar nada",paragraphs:["1. Elige una dirección o situación deseada. 2. Reúne algunas imágenes y palabras que la representen. 3. Ordénalas en papel, un tablero que tengas o una página digital. 4. Colócalas donde quieras volver a verlas. 5. Míralas e imagina la situación deseada. Estos pasos describen el ejercicio de sus practicantes; no demuestran que un tablero haga realidad esa situación. [manifest-P03]","En este curso, conserva una dirección en vez de añadir todas las mejoras posibles para tu vida. Basta una foto, un dibujo o una palabra que ya tengas. Bajo una imagen, nombra la tarea concreta: consultar sobre una capacitación, terminar una muestra o enviar una solicitud adecuada. Elige un lugar donde puedas actuar al verla. Tú decides los materiales y la disposición; la ciencia no exige comprar artículos especiales. Separa ordenar imágenes de completar la tarea."]},{heading:"Qué puede explicar la atención y qué no",paragraphs:["La atención depende de tus metas actuales, de qué tan llamativo sea un estímulo y de lo que has atendido antes. Es razonable buscar deliberadamente oportunidades relevantes; eso no valida cualquier método para detectarlas mejor. El sistema reticular activador participa en circuitos de vigilia y activación. Estos hallazgos no demuestran que el tablero controle un filtro que entregue empleo, pareja o casa. Una oportunidad recién detectada pudo existir antes de que le prestaras atención. [manifest-T15, manifest-T19]","ODA usa la imagen como recordatorio explícito, sin atribuirle un mecanismo oculto. Escribe la meta, la acción de hoy y una respuesta al obstáculo que podría interrumpirla. Si mirar el tablero inicia otra sesión de navegación, planea abrir primero tu archivo de trabajo. Mañana revisa si apareció la señal, si la notaste y qué hiciste. Anota por separado las respuestas externas. Esta combinación de imagen y plan no se ha probado como intervención con tableros de visión."]}],sources:["manifest-P03","manifest-T15","manifest-T19"]},{number:9,technique:"Afirmaciones",title:"Afirmaciones: una frase para actuar",goal:"Une una frase de ánimo a una acción observable.",hook:"¿«Tengo un éxito increíble» te suena falso? Prueba una frase que te diga qué hacer.",reason:"¿Te ayuda a actuar o te presiona a sentir certeza?",paragraphs:["Las afirmaciones son frases de ánimo dichas o escritas repetidamente, a menudo como resultados logrados. Elige una, repítela e imagina creerla. Evidencia mixta: Wood y colegas hallaron que una frase muy positiva empeoró el ánimo de algunos participantes con baja autoestima. La autoafirmación estudiada suele explorar valores, no lemas de éxito; sus hallazgos en salud no prueban que los lemas atraigan empleos.","Versión ODA: usa una frase que te sirva. Nombra un valor y cómo expresarlo: «Preparo un ejemplo honesto». Elige una meta concreta, un obstáculo y qué harás si aparece. Actúa hoy; mañana revisa qué hiciste. Cambia u omite la frase si te hace sentir peor."],example:{title:"Lucía cambia la frase",text:"Lucía repite «Hablo de maravilla» antes de una reunión y siente más vergüenza. Cambia a «Preparo una idea clara». En su escritorio escribe y ensaya una sugerencia. En la reunión dice la primera frase y pierde el hilo. Anota su aportación y la explicación pendiente."},instructions:["Elige una frase de ánimo ligada a un valor y una acción concreta.","Nombra un obstáculo y qué harás si aparece, sin exigirte creer.","Intenta la acción hoy; mañana revisa qué hiciste y cómo te sentiste."],action:["Usar una frase preparada en la reunión","Hacer una pregunta clara del proyecto"],minimum:["Decir la primera frase de mi sugerencia","Enviar una pregunta concreta del proyecto"],cue:["Cuando pidan sugerencias en la reunión","Al abrir la conversación del proyecto"],place:["En nuestra sala de reuniones","En los mensajes del proyecto"],obstacle:"Mi frase de ánimo me suena falsa",fallback:["Usar mi frase preparada sin afirmaciones","Usar un recordatorio sencillo de la acción"],observation:["Qué dije y cómo respondieron","Si ayudó o me hizo sentir peor"],stopRule:"Cambia u omite frases que te causen malestar; no tienes que obligarte a sentir certeza.",scenario:"La frase de éxito que Lucía repite le hace sentir peor. Quiere aportar una sugerencia útil en una reunión y ya tiene una frase provisional.",question:"¿Qué ajuste responde a ambas cosas?",options:[{key:"persist",text:"Mantener la frase de éxito varias sesiones más antes de cambiarla y seguir ensayando cómo va a decir su sugerencia.",feedback:"Ensayar puede ayudarla a prepararse, pero no tiene que insistir con una frase que empeora su ánimo. La sugerencia que ya preparó ofrece otra forma de empezar sin obligarse a creer."},{key:"action",text:"Usar un recordatorio sencillo u omitir la afirmación, y decir la frase preparada cuando pidan sugerencias en la reunión.",feedback:"Así conserva una aportación posible y atiende el malestar que sintió. Lucía puede revisar qué dijo y cómo le resultó el recordatorio. No necesita estar convencida de que habla de maravilla."},{key:"wait",text:"Preparar una afirmación más fuerte sobre sus cualidades y posponer la sugerencia hasta sentirse más convencida de lo que dice.",feedback:"Explorar valores no equivale a convencerse de una frase grandiosa. Esperar a creerla exige confianza para una acción ya preparada. Conviene que la aportación sea pequeña y que la afirmación siga siendo opcional."}],best:"action",takeaway:"La frase puede recordarte actuar. Lo que hagas te dará información concreta.",review:"¿Qué intentaste? ¿La frase ayudó, estorbó o no cambió nada?",deeper:[{heading:"La práctica habitual de repetir frases",paragraphs:["1. Elige un resultado o una cualidad personal. 2. Exprésalo de forma positiva, normalmente en presente. 3. Dilo o escríbelo repetidamente. 4. Imagina la situación deseada mientras usas la frase. 5. Vuelve a ella en un momento elegido. La frecuencia y las palabras cambian entre versiones; esta receta habitual no establece una cantidad ni una emoción científicamente obligatorias. [manifest-P04]","Puedes disfrutar la práctica sin asumir su mayor promesa. Para ODA, usa una frase que señale un trabajo que puedas intentar. «Preparo una idea clara» puede acompañar tus notas de la reunión. También puedes prescindir de la frase. Algo incómodo o difícil de creer no es una prueba que debas superar. Wood y colegas estudiaron una afirmación concreta y sus efectos inmediatos en el ánimo; ese resultado no muestra que toda frase amable sea dañina. [manifest-T06]"]},{heading:"Un valor y un lema de éxito son distintos",paragraphs:["En los estudios de autoafirmación, las personas suelen reflexionar sobre valores, cualidades o relaciones importantes antes de recibir información posiblemente amenazante. Epton y colegas reunieron experimentos con mensajes de salud: hallaron pequeños efectos promedio en aceptación e intenciones y un beneficio conductual en ese contexto. Esos procedimientos difieren de repetir un resultado deseado como si ya fuera cierto. No demuestran que decir «Conseguí el empleo» produzca una oferta laboral. [manifest-T07]","ODA retoma esa distinción sin afirmar que todo el ritual esté probado. Elige un valor, como la honestidad, y una forma de expresarlo en tu meta actual: preparar un ejemplo fiel de tu trabajo. Guarda cuándo actuar y tu mínimo. Escribe qué harás ante un obstáculo probable, como perder el hilo, e intenta tu frase hoy. Mañana anota qué aportaste y si la frase te sirvió. Omite la afirmación si añade presión; conserva la acción posible. [manifest-T06, manifest-T07]"]}],sources:["manifest-P04","manifest-T06","manifest-T07"]},{number:10,technique:"Visualización",title:"Visualización: ensaya lo que falta para llegar ahí",goal:"Elige una tarea, ensaya una dificultad e inténtala.",hook:"¿Te trabas con una pregunta de la entrevista? Ensáyala antes de imaginar la oferta.",reason:"¿Otra escena mostrará qué falta o aplazará una acción preparada?",paragraphs:["Visualizar es imaginar un acontecimiento deseado, a menudo con detalles sensoriales y la sensación de éxito. Acomódate, imagina la escena, participa mentalmente y repite si quieres. Evidencia mixta para manifestar: la simulación mental favoreció conductas posteriores en promedio, sin demostrar atraer acontecimientos. Un estudio inicial sobre exámenes favoreció imaginar el proceso en algunas comparaciones; el metaanálisis posterior no encontró un tipo claramente superior.","Versión ODA: conserva una escena breve del resultado; después ensaya tu tarea y un obstáculo. Elige una meta concreta y qué harás si aparece. Actúa hoy y revisa mañana. Ensayar sigue siendo preparación. Si no surgen imágenes, escribe los pasos; no necesitas imágenes vívidas ni sentir algo especial."],example:{title:"Bruno ensaya la respuesta",text:"Bruno imagina terminar una entrevista y ensaya explicar un período sin empleo. Si se queda en blanco, comenzará por las fechas. Después de almorzar, graba una respuesta y nota que omitió qué aprendió. Añade una frase. La respuesta aún necesita práctica y todavía no hay ningún resultado de la entrevista."},instructions:["Imagina brevemente el resultado; ensaya la próxima tarea y una dificultad probable.","Escribe una meta concreta y qué harás si aparece esa dificultad.","Intenta la tarea hoy; mañana revísala por separado del ensayo previo."],action:["Grabar una respuesta para practicar la entrevista","Enviar una sugerencia preparada para la reunión"],minimum:["Guardar una primera respuesta grabada","Enviar una frase con mi sugerencia"],cue:["Al terminar de almorzar","Cuando pidan aportes en la reunión"],place:["En mi escritorio de práctica","En los mensajes del equipo"],obstacle:"Me quedo en blanco al empezar",fallback:["Empezar con las fechas de mis notas","Leer el breve inicio que preparé"],observation:["La respuesta que grabé","La preparación y mi aportación, por separado"],stopRule:"Deja de imaginar si aumenta el malestar; usa notas de tareas y un momento durante el día.",scenario:"Bruno imaginó dos veces una entrevista exitosa. Su respuesta grabada todavía evita explicar el período sin empleo. Tiene cinco minutos antes de salir de casa.",question:"¿Cómo usar la imaginación para preparar lo que falta?",options:[{key:"rehearse",text:"Ensayar la primera frase sobre ese período, grabar una respuesta provisional y comprobar si incluye las fechas necesarias.",feedback:"Así la preparación atiende lo que falta y produce una grabación para revisar. Imaginar no asegura el resultado de la entrevista. Aquí sirve para ayudar a Bruno a intentar su respuesta."},{key:"outcome",text:"Repetir la escena de la entrevista exitosa con más detalles y anotar cuánta confianza siente después de imaginarla.",feedback:"La confianza puede observarse, pero no responde la pregunta pendiente. La grabación de Bruno señala una explicación concreta que necesita practicar. Usa el tiempo restante para ensayar y grabar esa explicación."},{key:"research",text:"Aprovechar el tiempo para comparar varios métodos de visualización antes de elegir cuál va a practicar esta noche.",feedback:"Comparar métodos puede interesarle, pero esta evidencia no exige uno concreto para empezar. Bruno ya sabe qué tarea falta. Intentarla brevemente aporta información más pertinente que seguir buscando otro método para visualizar."}],best:"rehearse",takeaway:"Busca una tarea en la escena. Ensaya para prepararte; actúa para probar.",review:"¿Qué intentaste después de ensayar? ¿Qué viste que aún faltaba?",deeper:[{heading:"La escena habitual del resultado deseado",paragraphs:["1. Elige un acontecimiento que deseas. 2. Acomódate en un lugar agradable. 3. Imagina una escena breve con el resultado esperado. 4. Imagínate participando, con detalles que te importen. 5. Vuelve a la escena si quieres. Algunas versiones piden emociones intensas o sentir que ya tienes el resultado. Estas instrucciones describen un ritual; no demuestran que la escena atraiga un acontecimiento externo. [manifest-P05]","Para ODA, deja la escena lo bastante breve para conservar tiempo para trabajar. Identifica la próxima tarea entre hoy y ese resultado. Ensaya mentalmente una dificultad y escribe cómo responderás. Si no formas imágenes vívidas, puedes describir los pasos. Es una opción de accesibilidad, no prueba de que todos los formatos de preparación tengan el mismo efecto. No anotes como real una respuesta de la empresa que solo has imaginado."]},{heading:"Ningún tipo de imagen gana siempre",paragraphs:["El estudio inicial de Pham y Taylor sobre exámenes comparó imaginar el proceso de estudiar, la nota deseada, combinaciones y un control. Algunas comparaciones favorecieron imaginar el proceso; el hallazgo sobre notas no justifica un beneficio fiable frente al control. Después, Cole y colegas reunieron simulaciones mentales diversas y encontraron un beneficio conductual promedio, sin demostrar diferencias entre tipos. Varios subgrupos eran pequeños. Prometer que una escena siempre funciona mejor exageraría esta evidencia. [manifest-T17, manifest-T04]","ODA pregunta qué preparación necesita tu tarea. Si conoces la meta pero evitas su primera frase, ensaya empezar y responder a ese obstáculo. Guarda un mínimo posible, una señal, un lugar y una respuesta. Intenta la acción hoy y revisa mañana. Anota por separado el ensayo útil y cualquier tarea realizada. Si sigues preparándote sin actuar, acorta la preparación o elige otro momento disponible. Esta secuencia de escena e intento es una adaptación ODA, no un protocolo validado por el metaanálisis."]}],sources:["manifest-P05","manifest-T04","manifest-T17"]},{number:11,technique:"Método 55x5",title:"55x5: reserva tiempo para la tarea",goal:"Combina escritura opcional con una acción posible y revísala.",hook:"¿Cincuenta y cinco renglones y la postulación en blanco? Reserva tiempo para postularte.",reason:"¿Cuánto puedes escribir sin quitarle tiempo a tu tarea?",paragraphs:["El 55x5 pide escribir una afirmación en presente 55 veces diarias durante cinco días. Elige un resultado, repite la misma frase y completa la cantidad diaria. Sin respaldo: que esa cantidad o duración atraigan un resultado. Algunos experimentos con fantasías idealizadas redujeron la energía inmediata; eso no demuestra que toda imaginación ni este ritual perjudiquen el esfuerzo.","Versión ODA: escribe si lo disfrutas; repetir es opcional. Elige una meta concreta y una acción posible cada día. Nombra el obstáculo y decide: si ocurre cierta situación reconocible, harás esto. Actúa hoy antes de escribir más; mañana revisa la tarea. La investigación respalda los planes específicos, no esa cantidad especial de repeticiones."],example:{title:"Santiago reserva tiempo",text:"Santiago disfruta copiar «Preparo buenas postulaciones», pero 55 renglones consumen todo su descanso. Escribe menos y reserva cinco minutos después del almuerzo para postularse. Si falta un dato, redactará una pregunta para el equipo de selección. Hoy envía la pregunta. Registra ese mensaje, sin contarlo como una postulación enviada ni una oferta."},instructions:["Elige una meta; reserva tiempo para actuar antes de decidir cuántas veces escribir.","Elige una situación reconocible y decide qué harás si aparece un obstáculo.","Intenta la tarea hoy y revísala mañana; las repeticiones son opcionales."],action:["Preguntar por un dato faltante","Completar una sección de la postulación"],minimum:["Enviar una pregunta al reclutador","Guardar una sección completa"],cue:["Al terminar el almuerzo","Después de escribir, si decido hacerlo"],place:["En el borrador del correo para selección","En mi mesa para postularme"],obstacle:"Las repeticiones consumen todo mi tiempo",fallback:["Omitir repeticiones y hacer el mínimo","Reservar tiempo para actuar antes de escribir"],observation:["Tarea hecha y tiempo de escritura por separado","Lo que envié o guardé"],stopRule:"Reduce u omite la escritura si te causa molestias o ocupa tu tiempo para actuar.",scenario:"Santiago completó dos días de 55 repeticiones. Ninguno le dejó tiempo para postularse. Hoy dispone del mismo descanso breve.",question:"¿Qué cambio le permite probar una rutina más útil?",options:[{key:"faster",text:"Escribir las repeticiones más rápido para conservar el ritual completo y quizá empezar la postulación después.",feedback:"Escribir más rápido aún puede dejar la postulación sin tiempo. Su registro muestra ese conflicto. Primero reserva un momento para una tarea posible; luego decide cuánto puede escribir sin ocuparlo."},{key:"weekend",text:"Completar los cinco días de escritura y dedicarle más tiempo a la postulación durante el fin de semana.",feedback:"Tal vez pueda hacerlo el fin de semana, pero posterga la tarea para respetar una cantidad sin respaldo. Hoy ya tiene una pequeña oportunidad. Pruébala antes de añadir más repeticiones."},{key:"reserve",text:"Reservar cinco minutos para una sección, reducir u omitir las repeticiones y revisar mañana lo que guardó.",feedback:"Esto cambia la condición que impedía trabajar. Puede seguir escribiendo por gusto y también avanzar en la postulación. Guardar una sección es prepararse para enviarla; aún no significa recibir una oferta."}],best:"reserve",takeaway:"Reserva tiempo para actuar. Completar las repeticiones no equivale a hacer la tarea.",review:"¿Qué tarea intentaste y cuánto tiempo te dejó la escritura para hacerla?",deeper:[{heading:"La conocida receta de cinco días",paragraphs:["1. Elige un resultado que quieras. 2. Escribe una frase positiva como si ya hubiera ocurrido. 3. Cópiala 55 veces en una sesión diaria. 4. Repite la sesión durante cinco días. 5. Mientras escribes, vuelve a pensar en el resultado. La cantidad exacta pertenece a la receta de quienes practican el método; no es una dosis establecida por estudios controlados. Algunas versiones añaden indicaciones sobre las emociones o la concentración ininterrumpida. [manifest-P06]","Puedes conservar la escritura si la disfrutas, pero observa cuánto tiempo ocupa. Antes de empezar, decide cuánto necesita la tarea de hoy. En ODA puedes escribir menos o no repetir. Saltarte un día no cancela un resultado futuro. Registra una página terminada como escritura y una sección guardada como trabajo en la postulación. Ninguna de las dos significa que una empresa te haya ofrecido empleo."]},{heading:"Lo que ayuda al plan no es repetir",paragraphs:["El metaanálisis de Gollwitzer y Sheeran respalda vincular una situación concreta con una respuesta orientada a la meta, en tareas variadas. No estudia 55 repeticiones ni una regla de manifestación de cinco días. Kappes y Oettingen encontraron que algunas fantasías positivas idealizadas redujeron la energía inmediata. Sus experimentos breves advierten sobre imaginar algo terminado en vez de prepararse; no prueban que todo pensamiento optimista o frase repetida perjudique el esfuerzo. [manifest-T02, manifest-T05]","ODA usa la página para un plan práctico. Escribe tu meta, la tarea útil más pequeña y cuándo podrás hacerla. Si escribir ocupa todo el descanso, actúa primero. Si falta un dato para completar una sección, pregunta por él. Inténtalo hoy y revisa mañana: ¿llegó el momento previsto?, ¿qué hiciste?, ¿qué falta? Combinar escritura y acción es una adaptación, sin promesa de resultados en cinco días."]}],sources:["manifest-P06","manifest-T02","manifest-T05"]},{number:12,technique:"Método de los dos vasos",title:"Dos vasos: escribe cómo acercarte",goal:"Elige una acción posible y cómo responder a un obstáculo.",hook:"¿Viertes el agua sin saber por dónde empezar? Elige una acción que te acerque.",reason:"¿Cómo alcanzarías esa situación con tu tiempo y recursos actuales?",paragraphs:["Etiqueta un vaso con tu situación actual y otro con la deseada. Llena el primero, imagina el cambio, vierte el agua en el segundo y bébela. Sin respaldo: que el agua transmita intenciones o cambie dimensiones. La evidencia sobre metas trata de objetivos concretos, estrategias y comentarios sobre el avance, no de una explicación cuántica para verter agua.","Versión ODA: conserva los vasos como símbolos o dibuja dos círculos. Entre las etiquetas, escribe una meta concreta, un obstáculo real y un plan «si pasa esto, haré esto». WOOP nombra deseo, resultado, obstáculo y plan; combinarlos ayuda en promedio según la investigación. Intenta hoy una acción para acercarte. Mañana revisa tu acción, separada de cualquier resultado externo."],example:{title:"Omar se acerca",text:"Omar etiqueta los vasos «Portafolio incompleto» y «Listo para postularme». Añade una nota: «Guardar la descripción de un proyecto después del almuerzo». Si no sabe explicarlo, describirá su decisión principal. Vierte el agua y escribe la descripción. Todavía le falta otro proyecto; anota exactamente qué cambió."},instructions:["Etiqueta la situación actual y la meta deseada; el cambio debe ser posible.","Entre ambas, escribe la acción de hoy y qué harás si aparece un obstáculo.","Intenta esa acción; mañana revisa el trabajo que hiciste."],action:["Escribir la descripción de un proyecto","Preguntar por un requisito de capacitación"],minimum:["Guardar una descripción de una decisión","Enviar una pregunta sobre capacitación"],cue:["Al terminar el almuerzo","Cuando guarde los vasos"],place:["En el documento de mi portafolio","En la mesa de mi cocina"],obstacle:"La etiqueta deseada requiere más recursos",fallback:["Preguntar por acceso o una opción más sencilla","Explicar una decisión del proyecto con palabras sencillas"],observation:["La acción que hice para acercarme","Lo que falta entre ambas etiquetas"],stopRule:"Puedes usar dibujos; si eliges beber el agua, usa únicamente agua potable.",scenario:"El vaso deseado de Omar dice «Listo para postularme». Su portafolio tiene un proyecto terminado sin descripción y otro proyecto todavía incompleto.",question:"¿Qué acción puede acercarlo en los cinco minutos disponibles?",options:[{key:"caption",text:"Escribir y guardar la descripción del proyecto terminado y anotar qué falta para que el portafolio esté listo.",feedback:"Elige una tarea posible y mantiene visible lo que falta. Una descripción no deja listo todo el portafolio, pero aporta un avance concreto que podrá examinar cuando vuelva a revisarlo."},{key:"rename",text:"Cambiar la etiqueta deseada a «Diseñador contratado» para tener presente su aspiración mayor durante el ritual.",feedback:"La aspiración mayor puede importarle, pero cambiar la etiqueta no resuelve el portafolio incompleto. Puede conservar esa aspiración y elegir una tarea pequeña que quepa en los cinco minutos disponibles."},{key:"schedule",text:"Organizar todas las tareas pendientes del portafolio antes de escribir la descripción, para tener completamente planeado el recorrido.",feedback:"Organizar las tareas puede servir al revisar más adelante. Ahora ya sabe que falta la descripción. Terminarla permite probar una acción posible sin gastar todo el rato en seguir preparando."}],best:"caption",takeaway:"Las etiquetas muestran qué falta. Una acción posible permite recorrer parte del camino.",review:"¿Qué cambió con tu acción y qué falta todavía entre tus dos etiquetas?",deeper:[{heading:"El conocido ritual de los dos vasos",paragraphs:["1. Toma dos vasos y etiqueta el primero con tu situación actual. 2. Etiqueta el segundo con la que deseas. 3. Pon agua en el primero. 4. Imagina el cambio mientras la viertes en el segundo. 5. Bebe el agua y vuelve a pensar en la situación deseada. Algunos practicantes llaman a esto un salto de dimensión. La evidencia examinada no establece esa explicación metafísica. [manifest-P07]","Puedes conservar el cambio simbólico sin aceptar su explicación como un hecho. Para ODA bastan vasos que ya tengas o dos círculos dibujados. Escribe una acción entre las etiquetas antes de verter el agua. No des por asegurada una decisión ajena incierta. Escribir una descripción útil para tu portafolio es tu acción; conseguir empleo también depende de la empresa. Si bebes, usa agua potable. No necesitas comprar un recipiente especial."]},{heading:"Usa lo que falta para planear con WOOP",paragraphs:["WOOP organiza un deseo, el resultado buscado, un obstáculo actual y un plan. El metaanálisis del contraste mental con intenciones de implementación encontró un beneficio promedio modesto para alcanzar metas, con variación e indicios de sesgo de publicación. No estudió vasos ni agua. La teoría de metas también considera compromiso, comentarios sobre el avance, capacidad y complejidad de la tarea. Una etiqueta necesita un camino posible; una meta exigente sin acceso ni estrategia no basta. [manifest-T01, manifest-T11]","ODA te pide escribir cómo acercarte. Elige una tarea concreta para tu meta. Nombra un obstáculo al que puedas responder y revisa barreras externas, como falta de equipo o dinero. «Si no puedo usar la herramienta, preguntaré por otra opción disponible» convierte pedir apoyo en una acción. Guarda el mínimo y cuándo empezarás, inténtalo hoy y revisa mañana. Distingue lo que pediste del apoyo recibido. Los vasos con este plan son una adaptación, no un tratamiento combinado probado."]}],sources:["manifest-P07","manifest-T01","manifest-T11"]},{number:13,technique:"Método de la almohada",title:"Almohada: deja una tarea para mañana",goal:"Conserva la nota bajo la almohada para recordar una acción de día.",hook:"¿Tu deseo sigue bajo la almohada? Deja una nota que te recuerde actuar mañana.",reason:"¿Planear de día te dejaría dormir mejor?",paragraphs:["El método de la almohada consiste en poner un deseo escrito debajo de ella. Una receta común pide escribirlo como si ya fuera realidad, doblar el papel, colocarlo debajo y repetir o imaginar el resultado antes de dormir. Sin respaldo: que ese papel produzca un resultado externo, según la evidencia revisada. [manifest-P08, manifest-T19]","Versión ODA: conserva la nota, añade una meta concreta y un obstáculo probable, y escribe qué acción harás si ocurre cierta situación. Estos planes específicos tienen respaldo; la atracción especial al acostarte, no. Haz algo útil hoy y revisa mañana. Si seguir planeando te desvela, déjalo para el día. [manifest-T02, manifest-T19]"],example:{title:"Mensaje de mañana",text:"En la mesa de la cocina, Mariana escribe su deseo de empleo y envía una postulación adaptada. Añade a la nota: al terminar de recoger los platos del desayuno, revisar una vacante adecuada. A la mañana siguiente la revisa y empieza otra postulación. Le faltan detalles. Registra por separado el envío y el borrador incompleto; ninguna empresa ha respondido."},instructions:["Conserva la nota; añade tu meta y obstáculo antes de acostarte.","Escribe cuándo empezarás y qué harás; realiza una acción útil hoy.","Mañana revisa lo que intentaste, por separado del ritual de la almohada."],action:["Enviar una postulación adaptada","Preguntar a un contacto por una vacante"],minimum:["Enviar una postulación adecuada","Enviar una pregunta concreta"],cue:["Tras recoger los platos del desayuno","Después del descanso del almuerzo de hoy"],place:["En mi mesa de cocina","En mi espacio de trabajo"],obstacle:"Planear al acostarme me quita sueño",fallback:["Planear durante el almuerzo de mañana","Usar una nota durante el día"],observation:["Postulación enviada; respuesta aún desconocida","Pregunta enviada; respuesta registrada aparte"],stopRule:"Detente si el ritual retrasa el sueño. Planea de día; no necesitas repetir nada al acostarte.",scenario:"La nota de Mariana indica preguntar por una vacante adecuada en la mañana. Reescribirla al acostarse la desvela, aunque ya sabe cuándo preguntará mañana.",question:"¿Qué debería hacer esta noche?",options:[{key:"a",text:"Reescribir la nota una vez más y decidir mañana si todavía le parece buena idea preguntar por la vacante.",feedback:"Otra versión le quita sueño sin añadir un detalle necesario. Ya sabe cuándo actuar. Conserva la pregunta planeada y deja cualquier cambio adicional de la nota para el día."},{key:"b",text:"Dejar la nota como está, permitirse dormir y preguntar por la vacante cuando llegue la señal prevista.",feedback:"Esto protege su sueño y conserva el compromiso útil. Mañana podrá anotar si envió la pregunta, distinguiendo la respuesta de la empresa de la acción que ella misma hizo."},{key:"c",text:"Cambiar la pregunta de la mañana por una visualización más larga, durante el día, de la respuesta de la empresa.",feedback:"El día permite planear con más tiempo, pero así reemplaza una acción útil disponible. Imaginar una respuesta no envía el mensaje ni establece qué decidirá la empresa sobre su postulación."}],best:"b",takeaway:"Deja una nota breve y una señal para actuar de día.",review:"¿Qué acción intentaste después de escribir la nota? ¿Planear al acostarte te quitó sueño?",deeper:[{heading:"La conocida receta de la almohada",paragraphs:["1. Elige un resultado y escribe una frase en presente, como una oferta imaginada ya recibida. Es la receta de un practicante: esa frase expresa un deseo, no una noticia verificada. Puedes mantener el texto en privado. [manifest-P08]","2. Dobla el papel y colócalo debajo de la almohada. La guía añade detalles de escritura y doblado que describen la versión de ese autor. No son requisitos establecidos para obtener un resultado externo. Usa una nota común que ya tengas. [manifest-P08]","3. Lee o repite mentalmente la frase mientras te acomodas. Si disfrutas esa parte, imagina que el resultado se cumplió. Luego permítete dormir; no exijas imágenes claras, repeticiones ni un sentimiento concreto para poder terminar. [manifest-P08]","4. Vuelve a la nota otra noche si quieres. La guía describe un ritual conocido, no evidencia controlada de eficacia. Una revisión sobre circuitos de activación no demuestra que los deseos al acostarte eviten el pensamiento crítico ni produzcan acontecimientos externos. [manifest-P08, manifest-T19]"]},{heading:"Una nota para actuar de día",paragraphs:["Antes de acostarte, añade una indicación práctica pequeña. Escribe la meta concreta, el obstáculo previsto y una acción posible. Para buscar empleo: «Si ya recogí los platos del desayuno, enviaré una postulación adecuada. Si no entiendo el formulario, haré una pregunta concreta al equipo de selección». Separa de la acción los resultados inciertos, como una oferta. [manifest-T02]","El metaanálisis de Gollwitzer y Sheeran encontró un beneficio promedio para alcanzar metas con planes específicos de «si ocurre esto, haré esto», en contextos variados. No estudió papeles bajo almohadas ni demuestra que planear elimine el esfuerzo. La revisión sobre activación describe circuitos de vigilia que interactúan, no una vía subconsciente para cumplir deseos. Son afirmaciones distintas. [manifest-T02, manifest-T19]","ODA añade el intento de hoy y la revisión de mañana como opciones prácticas; esa combinación antes de dormir no se ha probado. Anota qué enviaste, preguntaste o completaste; distingue cualquier respuesta. Si editar la nota te desvela, déjala y busca un momento durante el día. Para actuar no necesitas terminar el ritual. [manifest-T02, manifest-P08]"]}],sources:["manifest-P08","manifest-T02","manifest-T19"]},{number:14,technique:"Método del susurro",title:"Susurro: ensaya una petición respetuosa",goal:"Convierte la conversación imaginada en una petición respetuosa bajo tu control.",hook:"¿Esperas que alguien responda tu mensaje? El ritual del susurro puede ayudarte a elegir tu próximo paso.",reason:"¿Puedo hacer una petición apropiada?",paragraphs:["El método del susurro consiste en imaginar una petición a otra persona. Una receta común pide relajarte, imaginar que te acercas, susurrar lo que quieres tres veces y salir de la escena. Sin respaldo: lograr a distancia que esa persona responda, según la evidencia revisada. Su consentimiento y sus límites también importan. [manifest-P09]","Versión ODA: conserva el susurro privado, elige una meta concreta y nombra el obstáculo. Ensaya una petición respetuosa que permita decir que no. Escribe un plan «si ocurre esto, haré esto» para una acción adecuada hoy; revísala mañana. Esa planificación tiene respaldo; sentirte seguro de una respuesta ajena no demuestra que esa persona aceptará. [manifest-T02, manifest-T13]"],example:{title:"Sin presionar",text:"Durante el almuerzo, Bruno imagina susurrar una petición de reunión sobre un proyecto. La convierte en un mensaje: «¿Podemos conversar diez minutos el jueves?». Su compañera responde que no tiene tiempo el jueves. Bruno anota el mensaje y la negativa, y pregunta si la próxima semana le sirve. El ritual no la obligaba a aceptar."},instructions:["Susurra en privado una petición respetuosa; deja que la otra persona pueda negarse.","Nombra meta y obstáculo; escribe qué harás si aparece y pide algo adecuado hoy.","Mañana revisa qué pediste y cómo respetaste la respuesta."],action:["Pedir una reunión breve sobre el proyecto","Preguntar por disponibilidad cuando corresponda"],minimum:["Enviar una petición clara de reunión","Hacer una pregunta pertinente"],cue:["Después del descanso del almuerzo de hoy","Cuando empiece la conversación acordada"],place:["En mi escritorio de trabajo","En nuestro lugar habitual de reunión"],obstacle:"Sigo editando una petición sencilla",fallback:["Pedirlo con una frase sencilla","Preguntar durante la conversación acordada"],observation:["Petición hecha; respuesta registrada aparte","Límite respetado; próximo paso elegido"],stopRule:"No contactes a quien ha rechazado el contacto. Imaginar algo en privado no anula los límites de otra persona.",scenario:"Bruno quiere una reunión. Su compañera dijo que esta semana está ocupada, pero lo invitó a preguntar por la próxima. Practicar el susurro le da tranquilidad.",question:"¿Qué próximo paso encaja con la información que tiene?",options:[{key:"a",text:"Preguntar una vez por la disponibilidad de la próxima semana y aceptar la respuesta sin insistir con más mensajes.",feedback:"Ella ofreció esa posibilidad; una pregunta clara la respeta. Él puede registrar por separado la petición y la respuesta. Sentirse tranquilo no le da derecho a disponer del tiempo de ella."},{key:"b",text:"Esperar que ella proponga una hora porque la conversación imaginada ya le parece completa.",feedback:"Puede elegir esperar, pero la conversación imaginada no preguntó por la próxima semana. Ella le dio una oportunidad apropiada para hacer una petición real, si la reunión todavía le importa."},{key:"c",text:"Enviar una explicación más cálida de por qué la reunión de esta semana significaría tanto para él.",feedback:"Aunque sea más cálido, el mensaje vuelve a pedir la semana que ella descartó. Usa la posibilidad que ofreció; sentirlo con más intensidad no es una razón para presionarla otra vez."}],best:"a",takeaway:"Ensaya tu petición; cada persona decide su respuesta.",review:"¿Qué pediste en realidad y cómo reaccionaste ante su respuesta o el límite que puso?",deeper:[{heading:"La conocida conversación imaginada",paragraphs:["1. Elige a la persona y la respuesta deseada. Según el relato del practicante, el ejercicio ocurre en la imaginación. Elegir una respuesta dice qué quieres tú; no muestra lo que quiere esa persona ni establece permiso para contactarla. [manifest-P09]","2. Relájate e imagina a esa persona en algún lugar. Imagina acercarte y susurrar la petición al oído tres veces. La cantidad pertenece a esta receta, no es una dosis científica para influir en alguien. Puedes adaptarla con los ojos abiertos o describiendo la escena. [manifest-P09]","3. Sal de la escena imaginada. Algunas versiones añaden un beso imaginado en la frente: otro detalle, sin evidencia de influencia a distancia. En ODA, conserva el ejercicio en privado y elige una petición respetuosa. La intimidad imaginada no equivale a consentimiento. [manifest-P09]","4. Decide si corresponde hacer una petición real. El relato describe el ritual, pero no demuestra telepatía ni control. Una persona puede negarse, guardar silencio o cambiar de opinión; repetir el susurro no la obliga a responder. [manifest-P09]"]},{heading:"Planea tu parte de la conversación",paragraphs:["Concreta la meta: pedir una reunión cuando haya tiempo es distinto de hacer que alguien te admire. Nombra un obstáculo al que puedas responder, como retrasar un mensaje breve por editarlo una y otra vez. Elige cuándo empezarás: «Si termina mi almuerzo, enviaré una pregunta clara sobre disponibilidad». Si la persona no quiere contacto, tu acción puede ser respetar ese límite. [manifest-T02, manifest-P09]","La investigación sobre intenciones de implementación respalda conectar una situación reconocible con una respuesta elegida. No establece control sobre quien la recibe. En tres muestras de encuestas en línea, Dixon y sus colegas asociaron creer en la manifestación con confianza y algunos riesgos financieros declarados. Esas asociaciones no prueban causalidad; el estudio tampoco evaluó susurros. Sentirte seguro no mide si otra persona está de acuerdo. [manifest-T02, manifest-T13]","El ensayo privado y la revisión al día siguiente son adaptaciones de ODA. Haz hoy una petición apropiada o guarda una ocasión acordada. Mañana anota qué pediste, cualquier respuesta recibida y si la respetaste. Si no responde, no des nada por hecho. Elige otro paso adecuado o detente; no registres la escena imaginada como una conversación real. [manifest-T02, manifest-P09]"]}],sources:["manifest-P09","manifest-T02","manifest-T13"]},{number:15,technique:"Diario de gratitud",title:"Gratitud: agradece sin negar lo difícil",goal:"Anota algo real que agradezcas y actúa sin negar una dificultad.",hook:"Puedes agradecer que una amiga te ayude y admitir que rechazaron tu postulación.",reason:"¿Qué agradeces sin esconder lo que necesita cambiar?",paragraphs:["En tu diario anotas lo que agradeces; a menudo explicas por qué y lo relees. Algunas versiones de manifestación agradecen por algo futuro como si hubiera ocurrido. Evidencia mixta: las intervenciones de gratitud muestran beneficios promedio pequeños para el bienestar frente a algunos controles, con poca ventaja sobre alternativas psicológicamente activas. Los resultados sobre síntomas son modestos; agradecer no basta como tratamiento ni demuestra atracción de sucesos futuros.","Versión ODA: conserva el diario y describe algo real. Escribe también tu meta concreta y una dificultad. Añade qué harás si aparece un obstáculo y una acción hoy, como agradecer una ayuda o pedir comentarios específicos. Mañana revisa tu acción y cualquier respuesta. Agradecer no exige esconder la decepción."],example:{title:"Ambos hechos",text:"Ana agradece que su amiga revisara la postulación y anota el rechazo. Después del desayuno pregunta qué frase inicial necesita mejorar. Enviará un mensaje breve si no pueden hablar por teléfono. La amiga no puede responder hoy. Registra la pregunta y la decepción, sin inventar comentarios."},instructions:["Escribe algo real que agradezcas y por qué; conserva visible cualquier dificultad.","Elige una acción útil para hoy y qué harás si aparece un obstáculo probable.","Intenta la acción; mañana revisa lo que hiciste y cualquier respuesta."],action:["Pedir comentarios sobre algo concreto","Agradecer una ayuda específica"],minimum:["Enviar una pregunta sobre la postulación","Enviar un agradecimiento específico"],cue:["Al terminar el desayuno","Cuando termine de escribir lo que agradezco"],place:["En mis mensajes","En la mesa de mi cocina"],obstacle:"Quien me ayuda no puede hablar por teléfono",fallback:["Enviar una pregunta breve y concreta","Elegir otra persona disponible para revisar"],observation:["Petición enviada y cualquier respuesta real","Agradecimiento y dificultad anotados con honestidad"],stopRule:"No te fuerces a agradecer; si el malestar persiste, busca apoyo más allá del diario.",scenario:"Ana agradece el apoyo de su amiga, pero le duele el rechazo de su postulación. La amiga ofreció responder por mensaje una pregunta concreta.",question:"¿Qué anotación y acción encajan con la situación?",options:[{key:"positive",text:"Anotar solo los momentos de apoyo de hoy y dejar el rechazo para cuando se sienta más agradecida.",feedback:"Puede escribir lo que agradece sin postergar un problema concreto. La amiga ofreció responder una pregunta: Ana puede aprovecharlo para preguntar algo útil y reconocer que el rechazo le duele."},{key:"both",text:"Anotar el apoyo y la decepción, y preguntar qué frase inicial haría más clara su próxima postulación.",feedback:"Así agradece algo que ocurrió y usa el apoyo disponible. El mensaje es una petición; todavía no recibió comentarios. Mañana podrá anotar cualquier respuesta y elegir qué cambiar en su texto."},{key:"future",text:"Agradecer la próxima oferta como si ya hubiera llegado y releer la entrada antes de pedir comentarios.",feedback:"Esa versión sobre el futuro es un ritual de practicantes, no la intervención de gratitud evaluada en las revisiones citadas. No confirma que haya una oferta. Un agradecimiento real y una pregunta concreta mantienen el diario conectado con los hechos."}],best:"both",takeaway:"Agradece algo real. Mantén visibles la dificultad y la siguiente acción útil.",review:"¿Qué agradeciste, qué acción intentaste y alguien te respondió?",deeper:[{heading:"El conocido diario de gratitud",paragraphs:["1. Abre un cuaderno o tu herramienta habitual para escribir. 2. Nombra algo que agradezcas. 3. Explica por qué te importa. 4. Añade algo más si quieres. 5. Relee la entrada cuando decidas. Un relato de primera mano describe este formato con motivos y relectura. Algunas variantes de manifestación agradecen por un suceso futuro deseado; esa afirmación difiere de agradecer la ayuda ya recibida. [manifest-P10]","En ODA basta un detalle cotidiano: una respuesta útil, una herramienta prestada o un rato de descanso. No necesitas algo positivo para cada problema. Si hoy importan un rechazo, una barrera de acceso o una decepción, anótalos junto al agradecimiento. Elige una acción útil que encaje con tu meta. Escribir permite reflexionar; agradecer a alguien o enviar una petición son acciones separadas. Ni escribir ni pedir garantizan una respuesta."]},{heading:"Beneficios pequeños y límites de comparación",paragraphs:["Davis y sus colegas encontraron beneficios promedio pequeños para el bienestar frente a algunos controles. La gratitud no superó alternativas psicológicamente activas para el bienestar; los resultados de ansiedad fueron inconcluyentes. Cregg y Cheavens encontraron cambios promedio modestos en síntomas de depresión y ansiedad combinados, mayores frente a listas de espera que a controles activos; el análisis separado de ansiedad fue inconcluyente. Esto no establece una dosis óptima, alivio garantizado ni gratitud suficiente como tratamiento. Tampoco estudia si agradecer al universo hace llegar acontecimientos futuros. [manifest-T09, manifest-T10]","ODA añade un plan práctico sin llamarlo la intervención estudiada. Concreta tu meta, nombra el obstáculo actual y decide qué harás si aparece. Si quien te ayuda no puede llamar, envía una pregunta concreta. Inténtalo hoy y revisa mañana. Distingue la petición de cualquier respuesta; la decepción también puede quedar anotada. Puedes omitir el agradecimiento si se siente forzado y aun así actuar o buscar apoyo."]}],sources:["manifest-P10","manifest-T09","manifest-T10"]},{number:16,technique:"Actuar como si / encarnar una identidad",title:"Actuar como si: practica antes de gastar",goal:"Expresa quién quieres ser con una acción a tu alcance.",hook:"¿Buscas sentirte profesional comprando ropa? Mejora primero una muestra de trabajo.",reason:"¿Qué acción expresa tu meta sin descuidar otros gastos?",paragraphs:["Actuar como si, o encarnar una identidad, es comportarte como alguien que ya logró lo que deseas. Elige la identidad, imagina sus rutinas y adopta acciones o símbolos. Evidencia mixta: las metas concretas y los comentarios pueden ayudar al desempeño; fingir que el resultado está asegurado no tiene un mecanismo de atracción demostrado. Las encuestas vincularon creer en la manifestación con algunos riesgos financieros, sin demostrar causalidad.","Versión ODA: conserva el ensayo y elige una acción bajo tu control cuyo costo puedas cubrir. Define meta, obstáculo y qué harás si aparece. Un profesional puede preparar una muestra útil o preguntar algo concreto. Actúa hoy y revisa mañana. Comprar símbolos es opcional; otra persona decide si acepta."],example:{title:"Rafael practica",text:"Rafael quiere ser analista independiente. Piensa comprar una silla cara, pero mejora una hoja de cálculo de muestra. Después de almorzar, revisa una operación y añade una explicación. Si no puede usar el programa, recurrirá a una herramienta gratuita disponible. La muestra quedó más clara; todavía no tiene cliente."},instructions:["Define quién quieres ser y una acción concreta cuyo costo puedas cubrir.","Decide qué harás si aparece un obstáculo; no prometas decisiones de otras personas.","Inténtalo hoy; mañana revisa qué hiciste y cuánto gastaste."],action:["Mejorar una muestra de trabajo","Hacer una pregunta concreta al cliente"],minimum:["Guardar una operación explicada","Enviar una pregunta sobre el proyecto"],cue:["Después de almorzar","Al abrir el archivo de muestra"],place:["En mi escritorio","En mi hoja de cálculo de muestra"],obstacle:"No puedo usar la herramienta prevista",fallback:["Usar una herramienta gratuita disponible","Escribir la explicación en un archivo de texto"],observation:["Trabajo hecho y dinero gastado","El cambio guardado en la muestra"],stopRule:"Gasta solo lo que puedas cubrir; no des por seguros ingresos inciertos ni el consentimiento ajeno.",scenario:"Rafael busca trabajo independiente, sin cliente confirmado. Una herramienta de pago consumiría dinero para necesidades básicas; una gratuita disponible sirve para preparar la muestra.",question:"¿Qué acción expresa mejor ese oficio hoy?",options:[{key:"sample",text:"Mejorar una muestra con la herramienta disponible, anotar el cambio y proteger el dinero para necesidades básicas.",feedback:"Así practica el oficio con un costo a su alcance y un resultado que puede revisar. No asegura un cliente, pero mejora algo que Rafael puede compartir. No necesita arriesgar lo básico por un símbolo incierto."},{key:"purchase",text:"Comprar ahora la herramienta de pago para que su espacio refleje la identidad profesional que quiere adoptar.",feedback:"Una herramienta sirve si la tarea la exige y puedes pagarla. Aquí la opción gratuita basta, mientras la compra compromete necesidades básicas. Ensayar una identidad no confirma ingresos futuros ni vuelve seguro ese gasto."},{key:"wait",text:"Esperar a tener un cliente confirmado antes de preparar una muestra, para evitar dedicar esfuerzo a un resultado incierto.",feedback:"Cuidar el dinero tiene sentido, pero puede preparar una muestra pequeña con los recursos disponibles. Esperar certeza también frena esta prueba a su alcance. Limita el esfuerzo a algo viable y revisa qué necesita mejorar."}],best:"sample",takeaway:"Practica con lo que puedes pagar. Distingue identidad, gastos y resultados ajenos.",review:"¿Qué acción intentaste, cuánto costó y qué resultado conoces hasta ahora?",deeper:[{heading:"Cómo se ensaya esa identidad",paragraphs:["1. Elige la situación o identidad que deseas. 2. Imagina un día común de esa persona. 3. Escoge acciones, objetos o rutinas asociados con esa vida. 4. Actúa como si el cambio ya hubiera ocurrido. 5. Observa cómo te sientes y repite si quieres. Un relato describe preparar ropa y equipaje como si el empleo estuviera confirmado. La oferta posterior es una anécdota, no una comparación controlada. [manifest-P11]","ODA conserva el ensayo, pero pide una acción cuyo costo puedas cubrir. Preparar una muestra, llegar con una agenda o hacer una pregunta clara puede servir a tu meta. No necesitas posesiones caras para practicar ese oficio. No actúes como si alguien hubiera dado su consentimiento o una empresa ya te hubiera contratado. Un futuro posible orienta tus pasos; todavía no es un recurso disponible."]},{heading:"Las metas necesitan comentarios y recursos",paragraphs:["La teoría de metas describe cómo los objetivos concretos y exigentes pueden favorecer el desempeño, considerando compromiso, comentarios, capacidad y complejidad. No demuestra que adoptar una identidad produzca por sí solo el resultado deseado. Dixon y colegas encontraron asociaciones entre creer en la manifestación y algunos riesgos financieros y quiebras declarados, sin establecer causalidad. La confianza o sentirse exitoso no equivalen a dinero ya recibido. [manifest-T11, manifest-T13]","ODA propone una acción antes de un símbolo. Define qué producirás hoy y cuánto tiempo o qué herramientas tienes. Decide qué harás ante un obstáculo probable, como no poder usar un programa; el mínimo debe quedar a tu alcance. Inténtalo hoy y revisa mañana. Anota por separado trabajo, costos y respuestas ajenas. Si una compra o promesa supone que el éxito ya llegó, cambia de rumbo. Esta combinación de identidad y acción es una adaptación; los estudios citados no la probaron como intervención para encarnar una identidad."]}],sources:["manifest-P11","manifest-T11","manifest-T13"]},{number:17,technique:"Carta de tu yo futuro",title:"Tu yo futuro: el martes difícil",goal:"Saca de la carta una acción viable esta semana.",hook:"¿Otro martes con todo encima? ¿Cómo lo resolvería tu yo futuro?",reason:"¿Qué futuro merece un paso a tu alcance esta semana?",paragraphs:["Esta carta imagina a tu yo futuro escribiéndole a quien eres hoy. Elige una fecha, describe la vida y los cambios, ofrece ánimo y relee. Evidencia mixta: los estudios sobre el mejor futuro posible hallaron beneficios promedio en bienestar y optimismo, no mensajes del futuro ni metas garantizadas. Ese ejercicio incluye trabajar por la vida imaginada.","Versión ODA: conserva la voz, pero incluye esfuerzo, ayuda y un día común difícil. Define tu meta, el obstáculo actual y qué harás si aparece. Elige una acción para hoy y una ocasión viable. Planear algo concreto tiene respaldo; combinar carta y plan es una adaptación. Mañana revisa tu intento, no si se cumplió la predicción."],example:{title:"Julia escribe",text:"Julia escribe una semana laboral más estable y cómo pide prioridades cuando chocan las tareas. Al abrir el correo laboral, envía una pregunta para aclararlas. Si su jefa no está disponible, usará el chat del equipo. La respuesta tarda. Su registro muestra la consulta enviada y una carga de trabajo aún sin resolver."},instructions:["Escribe desde tu yo futuro; incluye esfuerzo, ayuda y un obstáculo cotidiano.","Elige la acción y una señal concreta; decide qué harás si aparece el obstáculo.","Intenta el mínimo y mañana revisa lo que pasó."],action:["Preguntar qué tarea tiene prioridad","Reservar una ocasión viable para practicar"],minimum:["Enviar una consulta para aclarar prioridades","Confirmar un horario disponible de práctica"],cue:["Al abrir el correo laboral","Después de recoger la cena"],place:["En el chat del equipo","En la mesa de la cocina"],obstacle:"La persona que necesito no está disponible",fallback:["Usar el chat acordado del equipo","Elegir otra ocasión disponible para practicar"],observation:["Consulta enviada y respuesta recibida","El horario que confirmé"],stopRule:"Si la carta añade presión, imagina un futuro más cercano o menos exigente. También puedes pausar.",scenario:"La carta de Julia promete una semana equilibrada. Hoy chocan dos tareas urgentes y su jefa invitó al equipo a consultar prioridades por el chat.",question:"¿Qué vale la pena añadir a la carta?",options:[{key:"calendar",text:"Describir el calendario completo de una semana ideal antes de preguntar cuál de las tareas urgentes va primero.",feedback:"Un calendario puede orientar decisiones después, pero por sí solo no resuelve qué tarea va primero. Julia tiene dónde preguntar. Aprovecha esa ocasión y deja claro que la consulta sigue sin respuesta."},{key:"certainty",text:"Añadir más ánimo para confiar en el futuro y esperar hasta que la carga de trabajo resulte menos agobiante.",feedback:"El ánimo puede ayudar, pero esperar a sentirse diferente deja ambas urgencias compitiendo. Ya puede enviar una consulta breve. La carta debería ayudarla a dar ese paso sin predecir qué le responderán."},{key:"request",text:"Describir cómo pregunta por las prioridades en días difíciles y enviar una consulta por el chat acordado del equipo.",feedback:"Esto añade a la escena futura una acción que responde al obstáculo actual. Enviarla depende de ella; la respuesta sigue pendiente hasta llegar. Mañana podrá revisar la consulta y elegir qué hacer después."}],best:"request",takeaway:"Que tu voz del futuro diga qué hacer hoy y qué apoyo podrías necesitar.",review:"¿Qué paso de la carta intentaste y qué ayuda o resultado sigue pendiente?",deeper:[{heading:"El formato conocido de la carta",paragraphs:["1. Escoge un momento de tu vida futura. 2. Imagina ser tú en ese momento. 3. Dirige una carta a tu yo actual. 4. Describe qué cambió y cómo se siente la vida cotidiana. 5. Ofrece ánimo o consejos y relee. Un recurso de práctica documenta esta voz del futuro al presente y su enfoque comprensivo. Las fechas y los saludos son decisiones de formato, no ingredientes científicamente necesarios. [manifest-P12]","Para ODA, escribe sobre un futuro deseado sin presentarlo como mensaje o predicción. Incluye una dificultad cotidiana, el esfuerzo y la ayuda que podrías necesitar. Una semana más tranquila quizá requiera hablar de prioridades, no sentir más certeza. Conecta ese rumbo con tu práctica del curso. Subraya una acción viable para quien despertará mañana con los mismos recursos. Puedes imaginar un futuro cercano si pensar en uno lejano te pesa."]},{heading:"La esperanza también necesita volver al presente",paragraphs:["El metaanálisis sobre el mejor futuro posible encontró beneficios promedio en bienestar, optimismo y afecto positivo frente a grupos de comparación. Principalmente estudiantes jóvenes; ningún estudio cumplió todos los criterios de calidad. Ese futuro supone trabajar para alcanzarlo. Los hallazgos no establecen que las cartas predigan o produzcan eventos externos. Por separado, investigar planes «si..., entonces...» respalda conectar una señal concreta con una respuesta viable. Ninguna fuente probó esta combinación exacta. [manifest-T08, manifest-T02]","ODA usa la carta para elegir una acción. Define tu meta, identifica el obstáculo más cercano a la tarea de hoy y escribe «Si pasa eso, haré...» con una respuesta viable. Guarda señal, lugar y mínimo; inténtalo hoy o en la ocasión elegida. Mañana revisa qué ocurrió: una petición, tarea, demora o pausa. Si alguien no contestó, deja la respuesta pendiente. Ajusta el próximo paso sin tratar el futuro imaginado como si ya fuera evidencia."]}],sources:["manifest-P12","manifest-T08","manifest-T02"]},{number:18,technique:"Concentración de 17 segundos",title:"17 segundos: del temporizador a la acción",goal:"Usa una pausa que te guste para empezar, sin atribuir respaldo científico a ese tiempo.",hook:"Te distrajiste antes de los diecisiete segundos. Aún puedes dar el siguiente paso.",reason:"¿El temporizador me ayuda a empezar o me retrasa?",paragraphs:["El método propone sostener un pensamiento deseado sin contradicciones durante diecisiete segundos. Algunas versiones repiten cuatro intervalos, hasta sumar sesenta y ocho segundos. Sin respaldo en la evidencia revisada: que ese tiempo tenga un poder especial de atracción. Los estudios de activación previa no validan esas cantidades ni los rituales deliberados de deseos. [manifest-P13, manifest-T16]","Versión ODA: conserva los diecisiete segundos como pausa opcional y define meta y obstáculo. Planea qué harás si aparece, actúa hoy y revisa mañana. Los planes concretos tienen respaldo. Distraerte no exige reiniciar antes de actuar; el temporizador sirve para empezar, no es requisito para lograr resultados. [manifest-T02, manifest-P13]"],example:{title:"La pausa interrumpida",text:"Antes de almorzar, Ana pone diecisiete segundos para pensar en su portafolio. Una entrega la distrae. Deja el temporizador y sigue su plan: después de almorzar, enviar una muestra a un cliente adecuado. El cliente pide otro estilo. Ana registra el mensaje y los comentarios, en vez de reiniciar el ejercicio de concentración."},instructions:["Elige tu meta; los diecisiete segundos son una pausa opcional.","Define obstáculo y respuesta; da hoy un paso útil.","Mañana revisa la acción intentada y los comentarios que recibiste."],action:["Enviar una muestra pertinente","Pedir comentarios sobre un borrador"],minimum:["Enviar una muestra adecuada","Hacer una pregunta concreta para mejorar"],cue:["Después de almorzar hoy","Al terminar el temporizador opcional"],place:["En mi lugar habitual de trabajo","En la mesa de la biblioteca"],obstacle:"Reinicio cada vez que me distraigo",fallback:["Omitir el temporizador y enviar","Usar una señal escrita para actuar"],observation:["Muestra enviada; respuesta aparte","Pregunta hecha; comentarios pendientes"],stopRule:"Omite el temporizador si reiniciar retrasa la acción o te angustia. Los pensamientos no deseados no requieren corregirse con rituales.",scenario:"La muestra preparada de Ana responde al pedido del cliente. Una notificación interrumpió el temporizador. Tiene cinco minutos para enviarla antes de una reunión.",question:"¿Cómo puede aprovechar mejor esta ocasión?",options:[{key:"a",text:"Repetir una vez la concentración sin notificaciones y enviar si queda tiempo antes de la reunión.",feedback:"Quitar notificaciones puede ayudar en una pausa opcional, pero ya sabe qué tarea hará. Exigir otro intervalo sin interrupciones puede hacerle perder la ocasión útil que tiene ahora."},{key:"b",text:"Dejar tanto el ejercicio como el envío para una sesión más larga y sin interrupciones mañana.",feedback:"Otra ocasión puede servir cuando la tarea requiere más tiempo. Aquí la muestra está lista y hay cinco minutos disponibles; interrumpir un ritual no obliga a posponer el mensaje."},{key:"c",text:"Enviar ahora la muestra preparada y registrar el mensaje por separado de la pausa interrumpida.",feedback:"Así aprovecha la ocasión y anota lo que pasó. Envió la muestra y se interrumpió la pausa. Ninguno de esos hechos le dice qué decidirá el cliente."}],best:"c",takeaway:"Que el temporizador te indique cuándo actuar, sin volverse una condición para hacerlo.",review:"¿Qué acción útil intentaste? ¿El temporizador te ayudó a empezar o te hizo esperar?",deeper:[{heading:"Qué pide la receta de diecisiete segundos",paragraphs:["1. Elige una experiencia deseada o un pensamiento positivo. La enseñanza atribuida a Abraham por Esther y Jerry Hicks pide atender ese pensamiento sin otro que se le oponga. Esto describe el ritual; no es un procedimiento probado por la investigación. [manifest-P13]","2. Sostén el pensamiento diecisiete segundos. Algunas versiones encadenan cuatro intervalos hasta sumar sesenta y ocho segundos. Puedes usar un temporizador para conservar ese formato, pero la evidencia consultada no establece un umbral especial de atracción en ninguna de las dos duraciones. [manifest-P13, manifest-T16]","3. Observa si te distrajiste, sin convertirlo en un juicio sobre tu futuro. ODA elimina reiniciar como requisito para actuar. Las afirmaciones del maestro sobre cambiar la realidad con pensamientos o equivaler a muchas horas de trabajo no son hallazgos de la investigación revisada. [manifest-P13]","4. Termina la pausa y elige qué hacer. Los experimentos de activación previa usan señales en condiciones específicas; eso no equivale a concentrarte deliberadamente en un deseo cronometrado. Puedes conservar un intervalo que te guste en tu ritual sin darle autoridad científica. [manifest-T16, manifest-P13]"]},{heading:"Cuando termine, empieza tu acción",paragraphs:["Elige una acción antes de activar el temporizador. Para tu portafolio, podría ser enviar hoy una muestra adecuada. Identifica el obstáculo: reiniciar hasta concentrarte perfectamente. Escribe: «Si termina el temporizador, enviaré la muestra preparada, aunque me haya distraído». Si cronometrarte añade presión, usa otra señal visible para empezar. [manifest-T02]","El metaanálisis de Gollwitzer y Sheeran respalda, en promedio, los planes concretos «si..., entonces...» en tareas variadas. La revisión de Dai y colegas encontró un efecto promedio de activación previa, pero efectos menores y estadísticamente no concluyentes en su pequeño subconjunto de estudios prerregistrados. Esa incertidumbre no refuta toda activación previa. Ninguna revisión valida diecisiete o sesenta y ocho segundos, ni que pensamientos no deseados bloqueen resultados. [manifest-T02, manifest-T16]","La secuencia ODA de pausa y acción es una adaptación, no uno de esos protocolos. Mañana registra por separado la acción intentada, las respuestas externas y cómo te concentraste. ¿La pausa te ayudó a empezar o los reinicios consumieron la ocasión? Conserva, acorta u omite el temporizador según lo que observes. [manifest-T02, manifest-P13]"]}],sources:["manifest-P13","manifest-T02","manifest-T16"]},{number:19,technique:"Método de la caja",title:"Caja de deseos: ponle fecha a una acción",goal:"Conserva la caja y da un paso concreto y viable.",hook:"¿Tu caja acumula deseos sin avances? Elige una tarjeta y actúa hoy.",reason:"¿Qué deseo cabe en mi tiempo y recursos?",paragraphs:["El método guarda deseos escritos, imágenes u objetos significativos en un recipiente. La receta común consiste en elegir una caja, añadir intenciones y emociones deseadas, y volver a mirarlas mientras imaginas que se cumplen. Sin respaldo: que el recipiente produzca esos resultados. La evidencia revisada no lo demuestra. Una caja que ya tengas basta. [manifest-P14]","Versión ODA: conserva las tarjetas. Añade a una tarjeta una meta concreta, un obstáculo, respuesta «si..., entonces...» y una acción para hoy; mañana revisa tu intento. Contrastar una meta con obstáculos y planear cómo responder tiene respaldo. El seguimiento del progreso también mostró beneficios promedio. Esta adaptación de la caja no se probó como conjunto. [manifest-T01, manifest-T03]"],example:{title:"Tarjeta en acción",text:"En la mesa de la cocina, Luis guarda la tarjeta de un curso de fin de semana en una caja de zapatos usada. Anota «poco tiempo» y llama para preguntar por opciones de asistencia. No hay modalidad flexible. Mañana registra la llamada y elige otro curso, en vez de sumar deseos."},instructions:["Elige un recipiente que ya tengas y una tarjeta con una meta concreta.","Añade el obstáculo y qué harás si aparece; actúa hoy.","Mañana abre esa tarjeta y anota la acción que intentaste."],action:["Preguntar por modalidades de asistencia","Consultar un dato pertinente del programa"],minimum:["Enviar una pregunta concreta del curso","Hacer una consulta útil"],cue:["Después del desayuno de hoy","Cuando abran la línea telefónica"],place:["En la mesa de la cocina","En mi rincón tranquilo de trabajo"],obstacle:"Quizá el horario no me sirva",fallback:["Preguntar por otra modalidad","Contactar una alternativa adecuada"],observation:["Consulta enviada; horario informado","Alternativa contactada; respuesta pendiente"],stopRule:"Usa materiales que ya tengas. Si una opción supera tus recursos, cambia la acción o haz una pausa.",scenario:"La tarjeta del curso de Luis señala un choque de horarios. Hoy pueden responder sus preguntas. También tiene varias imágenes nuevas para añadir a la caja.",question:"¿Qué paso permite comprobar si este curso le sirve?",options:[{key:"a",text:"Preguntar a quien organiza por las modalidades de asistencia y anotar la respuesta en la tarjeta.",feedback:"Así comprueba el obstáculo señalado y registra lo que ocurre. La respuesta quizá descarte este curso; aun así, ayuda a Luis a elegir un siguiente paso viable."},{key:"b",text:"Añadir primero las imágenes nuevas para que la caja refleje toda la experiencia que desea.",feedback:"Las imágenes pueden seguir en su ritual. Pero no resuelven la duda sobre horarios. La ocasión de hoy le permite averiguar si de verdad puede asistir al curso."},{key:"c",text:"Elegir otro curso de inmediato, ya que el choque de horarios deja este en duda.",feedback:"Otro curso quizá encaje mejor, pero hoy pueden aclararle esta duda. Una consulta concreta le da información útil antes de decidir si necesita cambiar la meta o mantenerla."}],best:"a",takeaway:"Conserva la tarjeta, añade una acción viable y anota lo que ocurrió.",review:"¿Qué acción intentaste por ese deseo y qué aprendiste sobre el obstáculo de la tarjeta?",deeper:[{heading:"Prepara la conocida caja de deseos",paragraphs:["1. Elige una caja o recipiente. La guía de práctica usa la caja para guardar intenciones. ODA te pide algo disponible, como una caja de zapatos usada o un sobre. Comprar un objeto especial no forma parte de la tarea. [manifest-P14]","2. Escribe deseos en tarjetas o busca imágenes que los representen. La guía incluye por qué deseas cada resultado y cómo te sentirías al recibirlo. Puedes guardar esos detalles para ti; una etiqueta sencilla basta para conservar el formato. [manifest-P14]","3. Guarda las tarjetas o imágenes dentro. Vuelve a mirarlas e imagina recibir lo que deseas si disfrutas ese ritual. Estos pasos describen el método que alguien practica y relata en primera persona, no evidencia de que el recipiente produzca un evento externo. [manifest-P14]","4. Elige una tarjeta para conectarla con una ocasión real. La explicación de la guía sobre campos energéticos es una creencia, no un hallazgo científico establecido. Puedes conservar el recipiente simbólico y cambiar qué haces hoy con esa tarjeta. [manifest-P14]"]},{heading:"Escribe el obstáculo al reverso",paragraphs:["Deja el deseo o imagen al frente. Detrás, escribe la meta concreta, un obstáculo probable y una respuesta «si..., entonces...». Para un curso: «Si abre la línea telefónica, preguntaré por las modalidades. Si el horario no me sirve, consultaré una alternativa adecuada». Elige una acción viable para hoy; preparar la tarjeta no cuenta como hacer esa consulta. [manifest-T01]","El contraste mental con planes «si..., entonces...» conecta el resultado deseado, un obstáculo real y cómo responder. Su metaanálisis encontró un respaldo promedio modesto para alcanzar metas, con resultados variados y posible sesgo de publicación. Harkin y colegas hallaron beneficios promedio al promover el seguimiento de avances. Ninguna revisión probó una caja de manifestación ni demostró que mañana sea el mejor momento para revisar. [manifest-T01, manifest-T03]","Volver mañana da a la tarjeta un momento práctico de revisión en ODA. Anota qué preguntaste y qué aprendiste; distingue la consulta enviada de una respuesta útil o una inscripción. Cambia la meta si dinero, acceso o tiempo la vuelven inviable. La caja también puede guardar una tarjeta corregida, una meta en pausa o un intento que no salió como esperabas. [manifest-T01, manifest-T03]"]}],sources:["manifest-P14","manifest-T01","manifest-T03"]},{number:20,technique:"SATS: estado cercano al sueño",title:"SATS: termina la escena y duerme",goal:"Imagina con calma y ensaya un paso práctico sin retrasar el sueño.",hook:"¿Repites la escena perfecta al acostarte? Puedes parar y dar un paso útil mañana.",reason:"¿Esta escena me deja tiempo para dormir?",paragraphs:["SATS, estado cercano al sueño, consiste en imaginar una escena breve de logro mientras te relajas y te da sueño. Quienes lo practican eligen una escena que implica éxito, participan mentalmente y la repiten como real. Algunos se duermen. Veredicto: Evidencia mixta para ejercicios similares; Sin respaldo para lograr deseos mediante somnolencia. La simulación mental favorece la acción en promedio, sin demostrar una ventaja especial al acostarse. [manifest-P15, manifest-T04, manifest-T19]","Versión ODA: conserva una imagen tranquila. Define meta y obstáculo, planea qué harás si aparece y ensaya el primer paso. Actúa hoy y revisa mañana. No hace falta una escena perfecta. Para si repetir te desvela; dormir no mide tus creencias. [manifest-P15, manifest-T19]"],example:{title:"Una escena con límite",text:"Desde su escritorio, Natalia consulta sobre una capacitación. Al acostarse, imagina brevemente que asiste y ensaya preguntar el costo durante el almuerzo de mañana. Repetir la escena la despeja, así que para. Al día siguiente pregunta; el programa cuesta demasiado. Registra esa respuesta y busca una opción gratuita."},instructions:["Antes de acomodarte, anota tu meta, el obstáculo y qué harás si aparece.","Ensaya brevemente el primer paso; haz hoy una tarea útil.","Prioriza dormir; mañana revisa la acción que intentaste."],action:["Preguntar el costo del programa","Consultar un dato útil de acceso"],minimum:["Enviar una pregunta concreta del costo","Hacer una pregunta de acceso"],cue:["Después del almuerzo de hoy","Al abrir la oficina del programa"],place:["En mi lugar habitual de trabajo","En la mesa de la cocina"],obstacle:"Imaginar me desvela",fallback:["Ensayar con palabras durante el día","Omitir la imagen y preguntar directamente"],observation:["Pregunta hecha; respuesta aparte","Noté desvelo; dejé de imaginar"],stopRule:"Para si imaginar te despeja o angustia. Ensaya durante el día o sáltalo; protege el sueño.",scenario:"Natalia tiene un plan diurno claro para consultar costos. Repetir la escena SATS la mantiene despierta y todavía no siente que sea del todo real.",question:"¿Qué le conviene hacer ahora?",options:[{key:"a",text:"Simplificar la escena y seguir repitiendo hasta que resulte lo bastante convincente para terminar.",feedback:"Simplificar puede servir al ensayar durante el día, pero no necesita convencerse para parar. Repetir la mantiene despierta, así que continuar antepone el ritual al sueño."},{key:"b",text:"Terminar la escena, dormir y preguntar por los costos cuando llegue la señal durante el día.",feedback:"Ya sabe cuándo actuar. Parar protege el sueño sin abandonar la meta. Mañana puede registrar la pregunta que hizo y cualquier información sobre costos que haya recibido."},{key:"c",text:"Sustituir la consulta por una sesión SATS diurna más larga que sienta más fácil de controlar.",feedback:"El día quizá sea mejor para imaginar si quiere, pero una escena larga no resuelve el costo. Conserva la consulta real y trata cualquier ensayo como preparación."}],best:"b",takeaway:"La escena puede terminar sin sentirse perfecta; registra por separado lo que intentas hacer.",review:"¿Qué acción intentaste de verdad? ¿La escena te dejó dormir?",deeper:[{heading:"La escena según la enseñanza SATS",paragraphs:["1. Elige un resultado y una escena breve que indique que ya ocurrió. Las conferencias de Neville Goddard describen participar en una escena de logro, no mirarte desde fuera. Es su método, no una vía demostrada para cambiar eventos externos. [manifest-P15]","2. Siéntate o acuéstate cómodamente, cierra los ojos si quieres y relájate hasta sentir sueño. La fuente incluye ese estado en la práctica. ODA permite una adaptación con ojos abiertos o palabras y no te pide forzar la somnolencia. [manifest-P15]","3. Repite la escena breve imaginándola real. Algunas versiones permiten dormir con esa sensación; otras mantienen una atención suave. Puedes parar antes de que la escena convenza. No te mantengas despierto para cumplir un ideal imaginado. [manifest-P15]","4. Separa las afirmaciones metafísicas de la receta. Una revisión de la activación fisiológica describe circuitos del sueño y la vigilia que interactúan, no evidencia de que la somnolencia cumpla deseos. La enseñanza de Goddard de que no hace falta actuar no surge de investigar simulación mental. [manifest-P15, manifest-T19, manifest-T04]"]},{heading:"Ensaya un paso y cuida el sueño",paragraphs:["Antes de acomodarte, elige una meta concreta y nombra el obstáculo. Para una capacitación, quizá necesites comprobar si puedes pagarla. Ensaya brevemente cómo preguntarás, incluyendo qué harás si la respuesta descarta el programa. Esta es una adaptación práctica de ODA; no necesita reproducir la sensación ni la escena que indicaba Goddard. [manifest-P15, manifest-T04]","La síntesis de Cole y colegas encontró un beneficio promedio en la conducta mediante simulación mental, en estudios variados, principalmente con estudiantes. No estableció de manera fiable qué tipo de simulación es mejor ni una ventaja especial al acostarse. Tampoco la revisión de activación fisiológica muestra que la somnolencia permita eludir el pensamiento crítico o produzca resultados externos. La evidencia general sobre imaginar no valida cada afirmación de SATS. [manifest-T04, manifest-T19]","Elige una señal diurna para la pregunta real y haz hoy una consulta útil cuando corresponda. Mañana registra consulta y respuesta aparte de la imagen. Si imaginar te mantiene despierto, para y elige ensayar de día u omitirlo. La siguiente acción puede seguir programada aunque no termines la escena. Esta secuencia completa no se probó como intervención SATS. [manifest-P15, manifest-T04, manifest-T19]"]}],sources:["manifest-P15","manifest-T04","manifest-T19"]}],i=d.map(u),p=[...o,{id:"M01",title:"Wang, Wang y Gai · 2021 · Contraste mental con intenciones de implementación",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"24 efectos independientes de 21 artículos, 15,907 participantes: beneficio promedio modesto para alcanzar metas, g = .336 [.229, .443]. El ajuste por sesgo estimó .242 [.143, .342].",limitation:"Gran variación e indicios de sesgo de publicación. No se probaron este curso ni sus ejercicios breves. Los resultados no están garantizados."},{id:"M02",title:"Gollwitzer y Sheeran · 2006 · Planes específicos y logro de metas",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 pruebas independientes, 8,461 participantes: los planes específicos de «si pasa esto, haré aquello» favorecieron alcanzar metas en promedio, d = .65 [.60, .70].",limitation:"Evidencia antigua y diversa, sin registro previo uniforme. Los planes no eliminan el esfuerzo, la necesidad de recordar, las barreras prácticas ni la incertidumbre."},{id:"M03",title:"Harkin y colegas · 2016 · Seguimiento del progreso hacia metas",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"138 experimentos, 19,951 participantes en total. El análisis de logro de metas usó 18,398 participantes: d = .40 [.32, .48]. Un ajuste de sensibilidad por estudios pequeños estimó .19 [.10, .28].",limitation:"Variaban las metas e intervenciones. Las asociaciones entre moderadores no obligan a informar públicamente. No se validaron este registro, su calendario de revisión ni el curso ODA."},{id:"M04",title:"Cole y colegas · 2021 · Simulación mental y cambio de conducta",url:"https://link.springer.com/article/10.3758/s13423-021-01880-6",type:"research",finding:"94 estudios, 123 efectos, 5,685 participantes: efecto general de la simulación mental g = .49 [.37, .62]. La comparación general entre tipos no fue significativa.",limitation:"Principalmente estudiantes y simulaciones diversas. Imaginar solo el proceso aportó cinco efectos con una estimación inconcluyente. No hay un orden fiable entre tipos ni validación de este ejercicio breve."},{id:"M07",title:"Dixon, Hornsey y Hartley · 2025, en línea en 2023 · Creencia en la manifestación",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Tres muestras de encuestas en línea de Estados Unidos, 1,023 participantes: la creencia se relacionó con algunos reportes de riesgo financiero y bancarrota, pero no con ingresos ni educación reportados.",limitation:"Las asociaciones no prueban causalidad ni evalúan objetivamente cada técnica de manifestación. Los resultados financieros reportados no predicen el futuro de una persona."},{id:"M10",title:"Gollwitzer y Brandstätter · 1997 · Elegir un momento concreto para empezar",url:"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/gollwitzer_brandstatter_1997_-_implementation_intentions_effective_goal_pursuit.pdf",type:"research",finding:"El Estudio 2 encargó un informe a 86 estudiantes. Entre 36 personas identificables que entregaron el informe, 12/17 personas que planearon y 6/19 del grupo de control escribieron dentro de dos días.",limitation:"El 71% frente al 32% corresponde a quienes entregaron, no a todos los reclutados. Planear no aumentó la colaboración general. Tarea estudiantil concreta; no valida el curso ODA."},{id:"M11",title:"Oettingen y colegas · 2015 · Planificación y horas agendadas",url:"https://doi.org/10.1002/ejsp.2090",type:"research",finding:"El Estudio 1 analizó 84 estudiantes universitarios. La comparación prevista favoreció combinar contraste mental y planes condicionales en horas agendadas, p = .03; prueba general p = .057.",limitation:"Se midieron horas agendadas, no trabajo terminado ni productividad. Se excluyeron respuestas incompletas. No se probaron la adaptación breve del curso ni su clasificación de barreras externas."},{id:"M14",title:"NIMH · Ayuda para problemas de salud mental",url:"https://www.nimh.nih.gov/health/find-help",type:"guidance",finding:"La guía oficial ofrece vías de atención profesional y ayuda en crisis ante malestar, dificultades para funcionar o peligro inmediato.",limitation:"Es una guía, no un estudio de eficacia. ODA no diagnostica ni trata enfermedades mentales. Fuera de Estados Unidos, usa los servicios locales de atención y emergencias."},{id:"manifest-positive-fantasies",title:"Kappes y Oettingen · 2011 · Fantasías positivas idealizadas",url:"https://bpb-us-e1.wpmucdn.com/wp.nyu.edu/dist/c/6235/files/2019/02/kappes-et-al-2011-positive-fantasies-about-idealized-futures-sap-energu.pdf",type:"research",finding:"Cuatro experimentos, principalmente con estudiantes, encontraron menos energía inmediata tras algunas fantasías positivas idealizadas. El Estudio 3 comparó fantasías positivas con neutras o sin dirección, no con fantasías que cuestionaban el resultado.",limitation:"Experimentos pequeños y breves. No todo optimismo ni imaginación hace daño. No se midieron un ciclo repetido de fantasías ni una señal cerebral de metas cumplidas."},{id:"manifest-belief-study",title:"Dixon, Hornsey y Hartley · 2025, en línea en 2023 · Creencia en la manifestación",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Tres encuestas en línea de Estados Unidos, con 1,023 participantes en total, relacionaron la creencia en la manifestación con confianza y algunos reportes de riesgo financiero, incluida bancarrota reportada. Sin asociación con ingresos ni educación reportados.",limitation:"Las asociaciones no prueban causalidad ni evalúan objetivamente cada técnica. Los resultados reportados no predicen el futuro de una persona."},{id:"manifest-murphy",title:"Joseph Murphy · El poder de la mente subconsciente · Información editorial",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"La editorial identifica el libro popular de autoayuda de Murphy y sus enseñanzas sobre imaginación y creencias.",limitation:"Sinopsis editorial, no estudio controlado. No se verificaron los pasajes exactos del ritual nocturno. Aquí no hay evidencia de atraer riqueza, sanar ni aprender mejor exclusivamente al acostarse."}],n=[{schemaVersion:2,revision:2,id:"manifest-1",courseId:"manifest",locale:"es",title:"¿Tu sueño sigue esperando? Haz algo útil",goal:"Produce algo que puedas usar para avanzar hacia una meta que tú elijas.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"¿Otra semana deseando una vida distinta? Haz algo concreto para acercarte a un deseo.",reason:{id:"manifest-1-reason",label:"¿De quién es esta meta? ¿Qué merece tu tiempo?",kind:"text",maxLength:160,optional:!0,suggestions:["Meta propia; las redes pueden esperar","Prioridad familiar; pulir puede esperar","Meta ajena; revisar cuánto tiempo dedicarle","No sé de quién es esta meta"]},why:{id:"manifest-1-purpose",label:"¿Qué te permitiría hacer este paso durante la semana?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Conseguir un mejor empleo es un resultado. Mejorar una frase de tu currículum es algo que puedes hacer. Otras personas deciden si te llaman. Elige trabajo que valga la pena sin usar su respuesta para medir tu esfuerzo.","En un experimento con estudiantes, elegir cuándo y dónde empezar mejoró la puntualidad entre quienes entregaron un informe. No aumentó la colaboración general. Un plan puede ayudarte a empezar; no garantiza resultados. Hoy, escribe una frase útil, responde una pregunta o pide algo concreto. Mantén esta meta durante el curso y vuelve con lo que haya ocurrido."],example:{title:"Daniel empieza por una frase",text:"Después de cenar, Daniel dedica diez minutos en la mesa de la cocina a buscar empleo en logística. Reescribe una frase del currículum sobre cómo organizó ocho turnos de almacén. Todavía suena torpe. La guarda y anota el cambio. Ningún empleador la ha visto. Mañana podrá mejorar un borrador que ya existe."}},move:{invitation:"Elige algo útil. Las sugerencias muestran el currículum de Daniel.",instructions:["Antes de guardar, nombra el documento, la pregunta o el objeto que cambiarás.","Haz tu mínimo. Anótalo aparte de cualquier respuesta que recibas."],prompts:[],suggestions:{action:["Reescribir una frase del currículum sobre turnos","Preguntar qué detalle falta en mi currículum","Crear una muestra de cobertura de turnos"],minimum:["Guardar una frase del currículum sobre turnos","Enviar la pregunta sobre el currículum","Guardar una muestra de cobertura de turnos"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1},{label:"En dos días",daysFromToday:2}],cue:["Después de recoger la mesa","Al terminar el almuerzo","Después de mi bebida de la mañana"],place:["En la mesa de mi cocina","En una mesa de la biblioteca","En el documento de mi currículum"],minutes:[10,2,5],fallback:["Describir un cambio de turno con palabras sencillas","Elegir otro momento disponible y nombrarlo","Preguntar por computadoras en la biblioteca"],observation:["La frase del currículum que guardé","Si envié la pregunta sobre el currículum","Qué me impidió hacer el mínimo"]},suggested:{action:"Reescribir una frase del currículum sobre turnos",minimum:"Guardar una frase del currículum sobre turnos",minutes:10,cueHint:"Después de recoger la mesa",placeHint:"En la mesa de mi cocina",obstacleHint:"Tengo menos tiempo del que había previsto",fallbackHint:"Describir un cambio de turno con palabras sencillas",observationHint:"La frase del currículum que guardé"},accessibleAlternative:"Escribe, dicta o usa tus herramientas habituales. Pide ayuda práctica si la necesitas.",stopRule:"Detén los pasos inseguros o que no puedes pagar. Busca apoyo práctico."},result:{question:"¿Hiciste tu mínimo elegido?",observationPrompt:"¿Qué hiciste o produjiste al ponerlo en práctica?"},judgment:{primary:{id:"manifest-1-decision",scenario:"Daniel encontró una vacante adecuada y tiene diez minutos antes de cenar. Su currículum no describe la organización de turnos que exige el puesto.",question:"¿Cuál sería la mejor primera prueba?",options:[{id:"manifest-1-research-more",text:"Comparar más vacantes para comprobar si este puesto encaja con la vida que quiere.",feedback:"Comparar puestos puede aclarar una meta. Esta vacante ya encaja. Lo que falta es una descripción útil de la experiencia de Daniel. Mejora esa frase con el tiempo disponible."},{id:"manifest-1-improve-line",text:"Reescribir una frase del currículum para esta vacante, guardar el borrador y anotar qué falta mejorar.",feedback:"Así Daniel produce algo útil sin pasar de diez minutos. El borrador quizá necesite comentarios y el empleador podría no responder. Nada de eso borra el trabajo que hizo."},{id:"manifest-1-clarify-future",text:"Describir con detalle su jornada ideal antes de decidir qué incluir en el currículum.",feedback:"Imaginar una jornada deseada puede orientar decisiones posteriores. Daniel ya eligió un puesto adecuado. Seguir describiéndolo aplaza algo concreto que falta. Escribe la frase y después revisa qué necesita."}],bestOptionId:"manifest-1-improve-line"}},carry:{takeaway:"Haz algo útil por tu deseo. Anota ese paso aparte de la respuesta que esperas.",followUp:{questionId:"manifest-1-return",question:"¿Qué trabajo útil quedó después del intento que guardaste?",observationPrompt:"¿Qué pasó en el momento que habías elegido?",adjustmentPrompt:"¿Qué cambio harías para tu próxima oportunidad?"}},goDeeper:{sections:[{heading:"Para qué sirve planear el inicio",paragraphs:["En el Estudio 2 de Gollwitzer y Brandstätter, de 1997, 86 estudiantes de Múnich recibieron un encargo sobre Navidad. Quienes planearon eligieron una hora y un lugar exactos, imaginaron ese momento, se comprometieron a empezar y anotaron sus decisiones. Entre las 36 personas identificables que entregaron el informe, 12 de 17 personas que planearon y seis de 19 del grupo de control escribieron dentro de los dos días indicados. Esos porcentajes corresponden a quienes entregaron, no a todas las personas reclutadas. Planear no aumentó la colaboración general. [M10]","Esta lección toma la idea de elegir un momento concreto y te pide hacer algo útil cuando llegue. Esa adaptación a otras tareas no se probó en el estudio del informe navideño. Una fecha por sí sola no explica de dónde sacarás el tiempo. Elige algo que puedas reconocer y un lugar al que puedas acceder. Si faltan recursos, pedirlos puede ser tu paso concreto. Anota esa petición como tal, aunque todavía no llegue la ayuda."]},{heading:"Un deseo no decide por otras personas",paragraphs:["Wang y sus colegas reunieron en 2021 24 efectos independientes de 21 artículos, con 15,907 participantes. Combinar un resultado deseado, un obstáculo y un plan condicional mostró un beneficio promedio modesto para alcanzar metas: g = .336, con un intervalo de confianza del 95% entre .229 y .443. Los hallazgos variaron mucho y un ajuste por sesgo de publicación redujo la estimación. Respalda planear con límites; no promete resultados para este curso. [M01]","Dixon y sus colegas estudiaron la creencia en la manifestación en tres encuestas estadounidenses en línea, con 1,023 participantes. Esa creencia se relacionó con algunos reportes de riesgo financiero y bancarrota, pero no con ingresos ni educación reportados. Las relaciones no prueban que la creencia causara bancarrota ni evalúan objetivamente cada ejercicio. [M07] Usa tu deseo para elegir qué hacer y evaluar las condiciones. No supongas que tus pensamientos atrajeron oportunidades, causaron dificultades o te hicieron merecer un resultado. Dinero, cuidados, acceso y decisiones ajenas siguen contando."]}],sourceIds:["M10","M01","M07"]}},{schemaVersion:2,revision:2,id:"manifest-2",courseId:"manifest",locale:"es",title:"¿Otro ensayo? Termina haciendo algo concreto",goal:"Ensaya un punto difícil y después avanza con algo concreto en la tarea que ya elegiste.",minutes:{learning:6,suggestedAction:5,review:2,rehearsal:1},direction:{hook:"Es fácil imaginar la vida que quieres. ¿Qué pasa cuando te toca enfrentar la página en blanco?",reason:{id:"manifest-2-reason",label:"¿Otro ensayo te ayudará o reemplazará el intento?",kind:"text",maxLength:160,optional:!0,suggestions:["Muestra una instrucción que falta","Retrasa una frase que ya puedo escribir","Aún no tengo un ensayo anotado"]},why:{id:"manifest-2-purpose",label:"¿Qué te permitiría hacer este paso durante la semana?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Retoma tu tarea y lo que hayas anotado. Ensayar es hacer mentalmente algo específico, como decir la primera frase. Enumerar los pasos es otra forma de prepararte. Ninguna de las dos equivale al intento real.","Una revisión encontró beneficios promedio de la simulación mental sobre la conducta, pero no estableció qué tipo era mejor. Tampoco demuestra que este ensayo breve funcione. Úsalo para detectar dónde te trabas y qué podrías hacer. Si no aparecen imágenes, descríbelo con palabras. Después escribe la siguiente frase útil de esa misma tarea."],example:{title:"Daniel enfrenta la línea en blanco",text:"Después de cenar, Daniel retoma su currículum. Durante treinta segundos ensaya cómo describir un cambio complicado de turnos. Cree que se quedará en blanco. Practica empezar con «Cambié ocho turnos cuando…». Después escribe una frase útil. Borra dos palabras y deja una pregunta para pedir comentarios. El ensayo no mostró cuánto detalle necesitaba."},rehearsal:{label:"Preparación opcional",steps:["Describe el siguiente paso y algo que podría trabarte.","Ensaya una vez qué harás primero. Esto es preparación."]}},move:{invitation:"Mantén tu tarea. Los ejemplos del currículum se pueden editar.",instructions:["Conserva tu acción, mínimo, señal y lugar. Trabaja en el punto que te traba.","Sin plan previo, elige qué harás y cuándo puedes hacerlo antes de guardar.","Ensaya una vez y actúa. Ensayar solamente es prepararte."],prompts:[],suggestions:{action:["Ensayar y escribir una frase sobre turnos","Ensayar y preguntar por un detalle del currículum","Corregir una fecha del currículum siguiendo pasos escritos"],minimum:["Guardar una frase del currículum después de ensayar","Enviar la pregunta sobre el currículum","Guardar una fecha corregida del currículum"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1},{label:"En dos días",daysFromToday:2}],cue:["Después de recoger la mesa","Al terminar el almuerzo","Al abrir el documento de mi currículum"],place:["En la mesa de mi cocina","En una mesa de la biblioteca","En el documento de mi currículum"],minutes:[5,2,10],fallback:["Dejar el ensayo y escribir un cambio real","Omitir imágenes y seguir el primer paso escrito","Preguntar a quien revisa qué detalle falta"],observation:["Lo que el ensayo no anticipó al actuar","La frase del currículum que escribí","Si solamente ensayé"]},suggested:{action:"Ensayar y escribir una frase sobre turnos",minimum:"Guardar una frase del currículum después de ensayar",minutes:5,cueHint:"Después de recoger la mesa",placeHint:"En la mesa de mi cocina",obstacleHint:"Sigo perfeccionando el ensayo en vez de empezar",fallbackHint:"Dejar el ensayo y escribir un cambio real",observationHint:"Lo que el ensayo no anticipó al actuar"},accessibleAlternative:"Escribe, dicta o usa tus herramientas habituales. Pide ayuda práctica si la necesitas.",stopRule:"Si planear en la cama te mantiene despierto, detente. Elige un momento durante el día."},result:{question:"¿Hiciste tu mínimo elegido?",observationPrompt:"¿Qué hiciste o produjiste al ponerlo en práctica?"},judgment:{primary:{id:"manifest-2-decision",scenario:"Daniel sabe cómo será su primera frase y tiene listo el documento. Le tienta volver a ensayar toda la solicitud.",question:"¿Qué paso ayuda a este intento?",options:[{id:"manifest-2-full-rehearsal",text:"Ensayar otra vez toda la solicitud para elegir el mejor comienzo antes de escribir.",feedback:"Un ensayo completo puede preparar trabajo posterior. Daniel ya tiene un comienzo útil y el documento listo. Repetirlo todo retrasa la prueba que puede hacer ahora. Escribe la frase y revísala."},{id:"manifest-2-new-goal-scene",text:"Imaginar su primer día en el puesto para recuperar motivación antes de retomar la solicitud más tarde.",feedback:"Imaginar el puesto puede aclarar por qué importa. No pone a prueba el comienzo que Daniel preparó. Escríbelo ahora en el documento. Después observa qué fue más difícil de lo esperado."},{id:"manifest-2-perform-opening",text:"Ensayar una vez la primera frase, escribirla en el borrador y comparar la dificultad con lo que esperaba.",feedback:"Así la preparación ayuda a actuar. La frase escrita le da a Daniel algo que revisar. Su calidad y su incomodidad siguen siendo preguntas abiertas. No son requisitos para reconocer el intento."}],bestOptionId:"manifest-2-perform-opening"}},carry:{takeaway:"Termina la preparación haciendo algo concreto. Anota cada cosa por separado.",followUp:{questionId:"manifest-2-return",question:"¿Qué cambió entre ensayar tu paso y hacerlo?",observationPrompt:"¿Qué pasó en el momento que habías elegido?",adjustmentPrompt:"¿Qué cambio harías para tu próxima oportunidad?"}},goDeeper:{sections:[{heading:"Lo que permite comparar la investigación sobre simulación",paragraphs:["La revisión de Cole y sus colegas, de 2021, reunió 94 estudios, 123 efectos y 5,685 participantes. La simulación mental mostró un efecto general sobre la conducta de g = .49, con un intervalo de confianza del 95% entre .37 y .62. La mayoría de las muestras eran estudiantes. Las simulaciones variaban en contenido, cantidad y resultados. Ese promedio no predice lo que pasará en tu ejercicio breve. [M04]","La revisión distinguió pensar los pasos de un proceso de realizar mentalmente una tarea. La estimación para imaginar solo el proceso usó cinco efectos y su intervalo de confianza incluyó la ausencia de efecto. La comparación general entre tipos no fue estadísticamente significativa. Los promedios mayores de algunos subgrupos no establecen un ganador fiable. Una gráfica no te obliga a visualizar con más fuerza. Esta lección usa el ensayo para descubrir un detalle práctico y después pide intentar la tarea. Describirlo por escrito es una opción de accesibilidad; no afirma equivalencia con las imágenes demostrada por la investigación."]},{heading:"Prepárate para un momento y después aprovéchalo",paragraphs:["En el experimento original de planificación del informe, las personas imaginaron una hora y un lugar específicos para empezar. La comparación de puntualidad se refería a las personas identificables que entregaron el informe y a una tarea estudiantil concreta. No establece un guion universal para imaginar ni un beneficio de ensayar en la cama. [M10] Aquí, prepararte vale la pena cuando te ayuda a hacer la siguiente parte de la tarea que ya elegiste para tu meta.","Quizá descubras que falta una contraseña, hay una instrucción poco clara o todavía no sabes explicar una frase. Restablecer la contraseña es preparación; enviar la información necesaria es hacer la tarea. Refleja esa diferencia cuando anotes lo ocurrido. Si planear al acostarte te mantiene despierto, detente y elige un momento diurno. Es una adaptación práctica del curso. El ensayo breve es opcional, no un ritual validado ni un requisito para empezar. No necesitas imágenes vívidas ni sentirte de una forma particular."]}],sourceIds:["M04","M10"]}},{schemaVersion:2,revision:2,id:"manifest-3",courseId:"manifest",locale:"es",title:"El obstáculo existe. Cambia las condiciones",goal:"Usa tu último intento para elegir y probar qué puedes hacer ante un obstáculo.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"¿Cuidar a tus hijos, falta de acceso o agotamiento? Creer con más fuerza no reorganiza tu día.",reason:{id:"manifest-3-reason",label:"¿Qué necesita apoyo? ¿Qué puedes cambiar ahora?",kind:"text",maxLength:160,optional:!0,suggestions:["Acordar cuándo usar la computadora compartida","Puedo reducir la edición del currículum","Los cuidados no dejan tiempo hoy","Todavía no he encontrado un obstáculo"]},why:{id:"manifest-3-purpose",label:"¿Qué te permitiría hacer este paso durante la semana?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Sigue con tu meta y revisa tus notas. ¿Aún no lo intentaste? Nombra una barrera probable. «No puedo usar la computadora después de cenar» orienta qué hacer. «Me falta disciplina» no identifica qué te frena.","Combinar un resultado deseado, un obstáculo real y un plan de «si pasa esto, haré aquello» mostró beneficios promedio modestos. Los estudios no establecieron que funcione por generar incomodidad. Dinero, cuidados, tiempo y acceso son condiciones, no fallas de tus creencias. Prueba un cambio: reducir la tarea, buscar un momento disponible o pedir apoyo específico. Pedir ayuda cuenta como pedirla, no como recibirla."],example:{title:"Daniel cambia de horario",text:"Daniel quería editar su currículum después de cenar, pero su hija necesitaba la computadora compartida para la tarea. Anota el conflicto. Pregunta si puede usarla diez minutos antes de cenar mañana. Acuerdan ese horario. Mejora una frase y se detiene. La solicitud todavía necesita trabajo."}},move:{invitation:"¿Falta acceso? Elige «Adaptar este paso» y «Apoyo». Indica a quién contactarás.",instructions:["Conserva acción, mínimo, señal y lugar si ya acordaron el acceso.","Si falta acceso, pide apoyo. Indica a quién, qué recurso necesitas y cuándo.","Anota por separado pedir, recibir ayuda y terminar la tarea."],prompts:[],suggestions:{action:["Pedirle usar la computadora compartida antes de cenar","Preguntar por horarios de computadora en la biblioteca"],minimum:["Pedir a mi hija diez minutos de computadora","Enviar la consulta sobre computadoras de la biblioteca"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1},{label:"En dos días",daysFromToday:2}],cue:["Al acordar horarios de tarea en casa","Después del almuerzo de hoy","Después de recoger la mesa"],place:["En la mesa de mi cocina","En el formulario de contacto de la biblioteca","En una mesa de la biblioteca"],minutes:[5,2,10],fallback:["Preguntar por computadoras en la biblioteca","Pedir en casa un horario de computadora","Pausar hasta acordar un momento viable"],observation:["La petición de acceso y cualquier respuesta","Si acordamos un horario de computadora","Si hice la edición elegida del currículum"]},suggested:{action:"Pedirle usar la computadora compartida antes de cenar",minimum:"Pedir a mi hija diez minutos de computadora",minutes:5,cueHint:"Al acordar horarios de tarea en casa",placeHint:"En la mesa de mi cocina",obstacleHint:"Mi hija no puede prestarme la computadora",fallbackHint:"Preguntar por computadoras en la biblioteca",observationHint:"La petición de acceso y cualquier respuesta",kind:"support"},accessibleAlternative:"Escribe, habla o pide asistencia. Elige «Adaptar este paso» para hacer la tarea cuando acuerden el acceso.",stopRule:"Si el ejercicio te abruma o el entorno es inseguro, detente y busca el apoyo adecuado."},result:{question:"¿Hiciste tu mínimo elegido?",observationPrompt:"¿Qué hiciste o produjiste al ponerlo en práctica?"},judgment:{primary:{id:"manifest-3-decision",scenario:"Daniel no puede editar de noche porque su hija usa la computadora para la tarea. Hay diez minutos antes de cenar si acuerdan compartirla.",question:"¿Qué harías ante este obstáculo?",options:[{id:"manifest-3-arrange-opening",text:"Acordar esos diez minutos disponibles y usarlos para mejorar una frase del mismo borrador.",feedback:"Esto cambia la condición que frenó la tarea y conserva un mínimo útil. Todavía hace falta acordarlo. Si no pueden confirmar el horario, anota la petición aparte."},{id:"manifest-3-keep-evening",text:"Mantener el horario nocturno y ensayar más tiempo para estar listo cuando pueda usar la computadora.",feedback:"Ensayar puede preparar las palabras, pero no resuelve el conflicto por la computadora. Daniel tiene otro horario posible. Acuérdenlo antes de agregar otra rutina de preparación."},{id:"manifest-3-wait-week",text:"Esperar a que disminuyan las tareas escolares la próxima semana y retomar la sesión larga que quería.",feedback:"Esperar puede ser adecuado cuando no hay un momento viable. Aquí podrían acordar uno más corto ahora. Prueba esa opción antes de aplazar automáticamente todo el trabajo."}],bestOptionId:"manifest-3-arrange-opening"}},carry:{takeaway:"Identifica la condición que te frena. Cambia la tarea o pide el apoyo necesario.",followUp:{questionId:"manifest-3-return",question:"¿Pediste acceso o hiciste la tarea? ¿Qué acuerdo sigue pendiente?",observationPrompt:"¿Qué pasó en el momento que habías elegido?",adjustmentPrompt:"¿Qué cambio harías para tu próxima oportunidad?"}},goDeeper:{sections:[{heading:"El obstáculo informa; no hay que provocarlo",paragraphs:["La revisión de 2021 sobre contraste mental y planificación encontró una mejora promedio modesta para alcanzar metas, con 24 efectos independientes. La gran variación y las señales de sesgo de publicación limitan la certeza. No aisló la incomodidad como ingrediente activo. Nombrar una dificultad puede ser desagradable, pero el ejercicio no busca aumentar deliberadamente tu malestar. [M01]","En el procedimiento de Oettingen y sus colegas, de 2015, se pidió a estudiantes detallar un resultado deseado y un obstáculo principal. Después elegían una respuesta, armaban un plan ante ese obstáculo y añadían hora y lugar habituales. En el Estudio 1, la comparación prevista favoreció el método en horas agendadas. Se midió lo programado, no el trabajo terminado, y la prueba general entre condiciones no fue concluyente. [M11] ODA añade comprobar la viabilidad y hacer un intento. Ese experimento no validó por separado este ejercicio breve ni su distinción entre condiciones externas y respuestas personales."]},{heading:"Cuando lo adecuado es pedir apoyo",paragraphs:["Separa lo que quieres lograr de las condiciones que necesitas para buscarlo. Si falta una herramienta, necesitas acceso. Si hay peligro, protección. Si debes cuidar a alguien, quizá otro horario. Esta elección del curso se apoya en la investigación sobre planes; no pretende clasificar cada obstáculo en una sola categoría. Una petición es concreta cuando dice qué ayuda necesitas y para qué momento. [M01, M11]","Si alguien no ha contestado, anota la petición y que falta respuesta. No anotes ayuda recibida ni tarea terminada. Puedes elegir otro paso viable, revisar la meta o pausar. Ante malestar persistente o dificultades importantes para funcionar, busca apoyo profesional en lugar de intensificar el ejercicio. La guía del NIMH ofrece vías de atención y ayuda en crisis; no demuestra que ODA trate una condición. [M14] Tu próxima nota debe describir lo que elegiste hacer, incluida la protección o el apoyo, sin convertir el obstáculo inicial en una falta de fe en ti."]}],sourceIds:["M01","M11","M14"]}},{schemaVersion:2,revision:2,id:"manifest-4",courseId:"manifest",locale:"es",title:"Deja de esperar a tener ganas",goal:"Elige una señal clara para empezar y un paso pequeño ante el punto que te trabó.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"«Cuando me sienta listo» se aplaza. Elige un momento que puedas reconocer.",reason:{id:"manifest-4-reason",label:"La última vez, ¿qué perdiste al posponer el paso?",kind:"text",maxLength:160,optional:!0,suggestions:["Comparé ejemplos; no escribí","Esperé sentirme listo; no toqué el borrador","Debía cuidar; no hubo un momento seguro","Sin señal previa; quizá me trabe al escribir"],help:"¿Aún no lo intentaste? Nombra una posible duda."},why:{id:"manifest-4-purpose",label:"¿Qué te permitiría hacer este paso durante la semana?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["La señal para empezar y el plan ante un obstáculo cumplen funciones distintas. «Después de recoger los platos, escribiré una frase del currículum» fija un momento. «Si me trabo, describiré un cambio de turno» te ayuda durante la tarea.","Con distintas metas, los planes de «si pasa esto, haré aquello» favorecieron actuar, en promedio. No eliminan toda necesidad de recordar, esforzarte o resolver barreras prácticas. Mantén tu tarea y atiende un obstáculo anotado, si existe. Elige una señal clara y algo que puedas hacer cuando llegue. Si no ocurre, elige «No hubo ocasión» y busca otro momento."],example:{title:"Daniel aprovecha la señal",text:"Daniel deja una nota junto a la computadora compartida: «Al recoger los platos, mejorar una frase. Si me trabo, describir un cambio de turno». El jueves reconoce el momento y ve la nota. Escribe una frase útil, pero no termina la sección antes de retomar sus responsabilidades familiares. Anota ambas cosas."}},move:{invitation:"Conserva tu tarea y horario. Ejemplo: el currículum de Daniel.",instructions:["Mantén tu acción, mínimo, señal y lugar, salvo que necesites cambiar algo.","Antes de guardar, elige un paso más pequeño ante el punto que te traba."],prompts:[],suggestions:{action:["Después de cenar, escribir una frase sobre turnos","Después del almuerzo, preguntar por el currículum","Después del té, corregir una fecha del currículum"],minimum:["Guardar una frase del currículum sobre turnos","Enviar la pregunta sobre el currículum","Guardar una fecha corregida del currículum"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1},{label:"En dos días",daysFromToday:2}],cue:["Después de recoger los platos","Al terminar el almuerzo","Al dejar mi taza de té"],place:["En la mesa de mi cocina","En el documento de mi currículum","En una mesa de la biblioteca"],minutes:[5,2,10],fallback:["Describir un cambio de turno en una frase","Elegir otro momento disponible y nombrarlo","Preguntar por computadoras en la biblioteca"],observation:["Si ocurrió la señal y la reconocí","Si describí el cambio de turno","El cambio del currículum que guardé"]},suggested:{action:"Después de cenar, escribir una frase sobre turnos",minimum:"Guardar una frase del currículum sobre turnos",minutes:5,cueHint:"Después de recoger los platos",placeHint:"En la mesa de mi cocina",obstacleHint:"Llega el momento, pero me trabo al escribir",fallbackHint:"Describir un cambio de turno en una frase",observationHint:"Si ocurrió la señal y la reconocí"},accessibleAlternative:"Escribe, dicta o usa tus herramientas habituales. Pide ayuda práctica si la necesitas.",stopRule:"Respeta tus responsabilidades de cuidado y seguridad. Busca otro momento si esta señal deja de servirte."},result:{question:"¿Hiciste tu mínimo elegido?",observationPrompt:"¿Qué hiciste o produjiste al ponerlo en práctica?"},judgment:{primary:{id:"manifest-4-decision",scenario:"Daniel tiene cinco minutos después de recoger los platos de la cena. Tiene un borrador y un ejemplo correcto de cambio de turno, pero se traba al escribir.",question:"¿Qué plan ayuda a empezar y a destrabarse?",options:[{id:"manifest-4-mood-cue",text:"Cuando piense con más claridad después de cenar, dedicar cinco minutos al currículum con sus mejores ejemplos.",feedback:"Pensar con más claridad sería agradable, pero no fija cuándo empezar. Usa el momento concreto de la cena y un paso que quepa en los cinco minutos disponibles."},{id:"manifest-4-full-section",text:"Después de recoger los platos, comparar tres ejemplos de turnos antes de elegir el mejor para el currículum.",feedback:"Comparar puede mejorar la elección. Daniel ya tiene un ejemplo correcto y buscar otros consumiría sus cinco minutos. Describe primero ese cambio. Revisa las palabras cuando exista una frase."},{id:"manifest-4-cue-and-response",text:"Después de recoger los platos, mejorar una frase. Si se traba, describir un cambio real de turno con palabras sencillas.",feedback:"Esto distingue qué hacer al empezar y al trabarse. Daniel puede probarlo con el borrador listo. El plan ayuda a actuar, sin prometer recordar sin esfuerzo ni terminar la sección."}],bestOptionId:"manifest-4-cue-and-response"}},carry:{takeaway:"Decide cuándo empezar y qué hacer si te trabas. Luego comprueba qué ocurrió.",followUp:{questionId:"manifest-4-return",question:"¿Reconociste la señal para empezar? ¿Pudiste hacer lo planeado?",observationPrompt:"¿Qué pasó en el momento que habías elegido?",adjustmentPrompt:"¿Qué cambio harías para tu próxima oportunidad?"}},goDeeper:{sections:[{heading:"Qué aporta un plan específico",paragraphs:["El capítulo de Gollwitzer y Sheeran, de 2006, reunió 94 pruebas independientes con 8,461 participantes. Los planes de «si pasa esto, haré aquello» mostraron un efecto promedio para alcanzar metas de d = .65, con un intervalo de confianza del 95% entre .60 y .70. Variaban las tareas y los procedimientos. Esta evidencia antigua no contó siempre con registro previo. No establece que cualquier frase que escribas vaya a funcionar. [M02]","El experimento de planificación pidió elegir hora y lugar específicos para empezar un informe. Su comparación de puntualidad se refería a las personas identificables que entregaron el informe, no a todas las personas asignadas a la tarea. [M10] La enseñanza práctica es más limitada que «un plan reemplaza la fuerza de voluntad». Decide qué harás y después comprueba si ocurrió la situación, si la reconociste y si el paso era adecuado. Conserva recordatorios externos si los necesitas. Una nota junto a una herramienta es una opción de ODA, no una garantía probada de que la verás."]},{heading:"Dos funciones en un mismo intento",paragraphs:["El horario elegido responde cuándo intentarás la tarea. Tu plan ante el obstáculo responde qué harás si aparece una dificultad observada. El procedimiento de contraste mental estudiado vinculaba un obstáculo con una respuesta y añadía hora y lugar habituales. No estableció que todas las personas necesiten dos reglas separadas. [M11] El curso distingue sus funciones para ayudarte a entender mejor lo que pasó en tu intento.","Supón que nunca llega el momento previsto. No hay razón para decir que falló el plan ante el obstáculo. Si llega y no lo reconoces, cambia la señal o el recordatorio. Si lo reconoces, pero el paso es demasiado grande, reduce el siguiente paso de la tarea. Son opciones que puedes probar, no hallazgos demostrados por un registro personal. Mantén las notas anteriores ligadas al mínimo original. Cambiar el próximo plan no convierte un intento anterior incompleto en trabajo terminado. Revisa lo que hiciste. Puedes pedir apoyo, descansar, pausar o cambiar de meta."]}],sourceIds:["M02","M10","M11"]}},{schemaVersion:2,revision:2,id:"manifest-5",courseId:"manifest",locale:"es",title:"¿Sin resultados? Mira lo que hiciste",goal:"Usa tus registros para elegir un siguiente paso viable y cuándo revisarás la próxima semana.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Antes de abandonar tu sueño, comprueba si probaste el camino o solo seguiste planeándolo.",reason:{id:"manifest-5-reason",label:"¿Qué te haría mantener, cambiar o dejar este camino?",kind:"text",maxLength:160,optional:!0,suggestions:["Borrador útil; enviarlo","Conflictos repetidos; cambiar el horario","Comentario concreto; revisar la frase confusa","Sin intento; elegir una primera prueba"]},why:{id:"manifest-5-purpose",label:"¿Qué te permitiría hacer este paso durante la semana?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Lee las notas de tu meta. Distingue lo planeado, ensayado y hecho de las respuestas de otras personas. Un borrador guardado demuestra que trabajaste. No demuestra que enviaste la solicitud ni que un empleador tenga interés.","Una revisión de 138 experimentos encontró beneficios promedio al aumentar el seguimiento del progreso. No validó este registro ni un calendario ideal de revisión. Elige según los hechos: repetir un paso viable, cambiar un problema, pedir comentarios o dejar una meta inadecuada. Si aún no lo intentaste, reconócelo y haz un primer avance concreto."],example:{title:"Daniel planea la próxima semana",text:"Daniel lee tres cambios que anotó con fecha y una ocasión en que no pudo usar la computadora. Su currículum es más claro, pero no ha enviado ninguna solicitud. Elige una vacante adecuada, revisa los requisitos y envía la versión preparada el viernes. Anota el envío y programa una revisión para la próxima semana. Todavía no hay respuesta."}},move:{invitation:"Conserva lo que sirvió y elige qué sigue. El ejemplo tiene una solicitud lista.",instructions:["Al repetir, conserva tu mínimo y horario. Cambia solo lo que observaste que te frenaba.","Sin registro previo, elige tu primera acción y un mínimo acorde antes de guardar.","Pedir información cuenta como pedirla, no como terminar la tarea bloqueada."],prompts:[],suggestions:{action:["Enviar la solicitud preparada para la vacante elegida","Consultar al contacto de contratación un requisito confuso","Revisar una frase del currículum según los comentarios"],minimum:["Enviar una vez la solicitud preparada","Enviar la pregunta sobre el requisito","Guardar la frase revisada del currículum"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1},{label:"En dos días",daysFromToday:2}],cue:["Al terminar el almuerzo","Después de recoger la mesa","Al abrir el formulario de la vacante"],place:["En la mesa de mi cocina","En una mesa de la biblioteca","En el formulario de solicitud de la vacante"],minutes:[10,2,5],fallback:["Consultar al contacto de contratación el requisito confuso","Pedir comentarios sobre la frase poco clara","Pausar hasta tener la información necesaria"],observation:["El envío y su confirmación, si existe","La pregunta y cualquier respuesta pendiente","Qué sigue fuera de mi control"]},suggested:{action:"Enviar la solicitud preparada para la vacante elegida",minimum:"Enviar una vez la solicitud preparada",minutes:10,cueHint:"Al terminar el almuerzo",placeHint:"En la mesa de mi cocina",obstacleHint:"No entiendo un dato obligatorio de la solicitud",fallbackHint:"Consultar al contacto de contratación el requisito confuso",observationHint:"El envío y su confirmación, si existe"},accessibleAlternative:"Escribe, dicta o usa tus herramientas habituales. Pide ayuda práctica si la necesitas.",stopRule:"No gastes más ni sacrifiques cuidados necesarios para salvar un resultado incierto."},result:{question:"¿Hiciste tu mínimo elegido?",observationPrompt:"¿Qué hiciste o produjiste al ponerlo en práctica?"},judgment:{primary:{id:"manifest-5-decision",scenario:"Daniel editó su currículum, pero aún no solicitó empleo. Una vacante adecuada cierra esta noche. Su borrador cumple los requisitos. Podrán comparar versiones mañana.",question:"¿A qué debería llevarlo esta revisión?",options:[{id:"manifest-5-next-application",text:"Enviar la solicitud preparada, anotar el envío y elegir cuándo revisará después, aunque todavía no conozca la respuesta.",feedback:"El registro muestra un siguiente paso concreto, listo y bajo el control de Daniel. Lo que hace es enviar. La decisión del empleador sigue siendo desconocida hasta que haya una respuesta real."},{id:"manifest-5-double-editing",text:"Pedir que comparen dos versiones del currículum antes de enviar la solicitud para evitar palabras poco convincentes.",feedback:"Compararlas podría revelar problemas de calidad, pero ocurriría después del cierre de esta noche. Daniel revisó los requisitos y no hay nada pendiente que él conozca. Envía esta versión adecuada. Usa los comentarios posteriores para cambiar algo concreto."},{id:"manifest-5-change-direction",text:"Aprovechar el tiempo para enviar varias solicitudes menos específicas y ampliar opciones antes de elegir qué versión conservar.",feedback:"Ampliar opciones puede crear oportunidades. Aquí ya hay una solicitud adecuada y lista. Enviarla pone a prueba esa opción. Aumentar la cantidad puede venir después, sin reemplazar este envío preparado para una vacante concreta."}],bestOptionId:"manifest-5-next-application"}},carry:{takeaway:"Lo ocurrido orienta tu siguiente paso. Esfuerzo, preparación y resultados externos aportan información distinta.",followUp:{questionId:"manifest-5-return",question:"¿Qué pasó con tu tarea o consulta? ¿Qué sigue pendiente?",observationPrompt:"¿Qué pasó en el momento que habías elegido?",adjustmentPrompt:"¿Qué cambio harías para tu próxima oportunidad?"}},goDeeper:{sections:[{heading:"Observar el progreso ayuda a decidir",paragraphs:["La revisión de Harkin y sus colegas, de 2016, incluyó 138 experimentos con asignación aleatoria y 19,951 participantes en total. El análisis de logro de metas usó 18,398 participantes y encontró d = .40, con un intervalo de confianza del 95% entre .32 y .48. Un ajuste de sensibilidad por estudios pequeños dio una estimación menor. Variaban las intervenciones, metas y formas de registro. La revisión no probó el resumen de ODA ni su tarjeta del día siguiente. [M03]","Entre estudios, los efectos mayores se asociaron con anotar o informar públicamente el progreso. Esas comparaciones no establecen que compartirlo sea necesario ni que un formato de aplicación cause beneficios. Mantén tus detalles en privado si te conviene. Usa tus notas para comparar lo que pedía el plan con lo que dijiste haber hecho. Sin registro, lo ocurrido queda sin confirmar. Una preparación terminada, una petición sin respuesta o un intento detenido deben conservar su nombre. Así puedes revisar tu siguiente decisión sin exigir una historia positiva."]},{heading:"Elige la próxima semana sin reescribir esta",paragraphs:["Un registro personal breve puede sugerir un patrón, pero no demuestra por qué ocurrió un resultado externo. Solicitudes, pedidos y respuestas ajenas pueden depender de calidad, horario, recursos o circunstancias que tus notas no miden. La investigación respalda usar información; no establece cuántos intentos deben hacerse antes de cambiar una meta. [M03] Al revisar, conserva esa incertidumbre. No atribuyas a un solo paso más de lo que sabes.","Elige un próximo momento viable y cuándo revisarás la semana que viene. Conserva tu mínimo útil y lo que facilitó el acceso. Cambia la parte que tus notas ponen en duda. Si no hay intentos anotados, cuenta los hechos conocidos o toma la siguiente acción pequeña como tu primera prueba. No inventes un historial de esfuerzo. Los estudios de planificación muestran beneficios promedio variables, sin garantizar resultados. [M01] Pausar, pedir comentarios, buscar apoyo práctico o elegir otro rumbo pueden ser decisiones deliberadas de la revisión. Conserva la nota anterior para que siga claro por qué cambiaste."]}],sourceIds:["M03","M01"]}},...i],m={id:"manifest",title:"¿Sueño estancado? Haz algo concreto",subtitle:"Cinco lecciones base y 15 técnicas populares: evidencia clara y una acción útil.",description:"Convierte un deseo propio en trabajo útil. Sigue con tu prueba en la biblioteca de técnicas: conoce los rituales, revisa la investigación e intenta un paso a tu alcance.",scope:"Aquí, manifestar significa elegir una intención, prepararte y actuar. El curso no afirma que tus pensamientos dirijan los acontecimientos mediante efectos cuánticos, que el universo te entregue aquello en lo que te concentras ni que todo deseo se cumpla. No ofrece asesoramiento financiero, médico ni psicológico.",outcome:"Una meta que te importa, un mínimo útil, registros honestos de tus intentos y un plan viable para la próxima semana.",lessonLibrary:{id:"manifest-technique-library",title:"Biblioteca de técnicas",description:"15 rituales conocidos: cómo se practican, qué respalda la investigación y una versión ODA para actuar y revisar lo ocurrido.",lessonIds:i.map(e=>e.id),sourceIds:o.map(e=>e.id)},photo:{id:"1676782778930-11b311ec5134",alt:"Camino de tierra que sube por una colina verde hacia montañas lejanas"},lessons:[{id:"manifest-1",v2:n[0],photo:{id:"1768055104910-8c8d213835fb",alt:"Mano que escribe una lista de pendientes en un cuaderno"},schemaVersion:2,title:"¿Tu sueño sigue esperando? Haz algo útil",minutes:6,goal:"Produce algo que puedas usar para avanzar hacia una meta que tú elijas.",reading:["Conseguir un mejor empleo es un resultado. Mejorar una frase de tu currículum es algo que puedes hacer. Otras personas deciden si te llaman. Elige trabajo que valga la pena sin usar su respuesta para medir tu esfuerzo.","En un experimento con estudiantes, elegir cuándo y dónde empezar mejoró la puntualidad entre quienes entregaron un informe. No aumentó la colaboración general. Un plan puede ayudarte a empezar; no garantiza resultados. Hoy, escribe una frase útil, responde una pregunta o pide algo concreto. Mantén esta meta durante el curso y vuelve con lo que haya ocurrido."],practice:["Escribe o piensa, en una sola frase, un deseo que te importe.","Elige algo que dependa de ti y te acerque a ese deseo.","Describe qué harás y dónde terminarás. Por ejemplo: «tres líneas de un borrador»."],reflection:"¿Qué puedes hacer hoy para acercarte a tu deseo?",question:"¿Cuál de estas acciones puedes elegir directamente?",options:["Que el empleador me elija sin falta.","Editar tres líneas de mi currículum mañana.","Que nada salga mal."],correct:1,feedback:"No puedes garantizar las decisiones ajenas. Sí puedes concretar tu propia preparación.",takeaway:"Haz algo útil por tu deseo. Anota ese paso aparte de la respuesta que esperas.",sources:["M10","M01","M07"],deeper:[{heading:"Para qué sirve planear el inicio",paragraphs:["En el Estudio 2 de Gollwitzer y Brandstätter, de 1997, 86 estudiantes de Múnich recibieron un encargo sobre Navidad. Quienes planearon eligieron una hora y un lugar exactos, imaginaron ese momento, se comprometieron a empezar y anotaron sus decisiones. Entre las 36 personas identificables que entregaron el informe, 12 de 17 personas que planearon y seis de 19 del grupo de control escribieron dentro de los dos días indicados. Esos porcentajes corresponden a quienes entregaron, no a todas las personas reclutadas. Planear no aumentó la colaboración general. [M10]","Esta lección toma la idea de elegir un momento concreto y te pide hacer algo útil cuando llegue. Esa adaptación a otras tareas no se probó en el estudio del informe navideño. Una fecha por sí sola no explica de dónde sacarás el tiempo. Elige algo que puedas reconocer y un lugar al que puedas acceder. Si faltan recursos, pedirlos puede ser tu paso concreto. Anota esa petición como tal, aunque todavía no llegue la ayuda."]},{heading:"Un deseo no decide por otras personas",paragraphs:["Wang y sus colegas reunieron en 2021 24 efectos independientes de 21 artículos, con 15,907 participantes. Combinar un resultado deseado, un obstáculo y un plan condicional mostró un beneficio promedio modesto para alcanzar metas: g = .336, con un intervalo de confianza del 95% entre .229 y .443. Los hallazgos variaron mucho y un ajuste por sesgo de publicación redujo la estimación. Respalda planear con límites; no promete resultados para este curso. [M01]","Dixon y sus colegas estudiaron la creencia en la manifestación en tres encuestas estadounidenses en línea, con 1,023 participantes. Esa creencia se relacionó con algunos reportes de riesgo financiero y bancarrota, pero no con ingresos ni educación reportados. Las relaciones no prueban que la creencia causara bancarrota ni evalúan objetivamente cada ejercicio. [M07] Usa tu deseo para elegir qué hacer y evaluar las condiciones. No supongas que tus pensamientos atrajeron oportunidades, causaron dificultades o te hicieron merecer un resultado. Dinero, cuidados, acceso y decisiones ajenas siguen contando."]}],example:{title:"Daniel empieza por una frase",text:"Después de cenar, Daniel dedica diez minutos en la mesa de la cocina a buscar empleo en logística. Reescribe una frase del currículum sobre cómo organizó ocho turnos de almacén. Todavía suena torpe. La guarda y anota el cambio. Ningún empleador la ha visto. Mañana podrá mejorar un borrador que ya existe."}},{id:"manifest-2",v2:n[1],photo:{id:"1517363898874-737b62a7db91",alt:"Persona sentada junto a una ventana iluminada con luz cálida"},schemaVersion:2,title:"¿Otro ensayo? Termina haciendo algo concreto",minutes:6,goal:"Ensaya un punto difícil y después avanza con algo concreto en la tarea que ya elegiste.",reading:["Retoma tu tarea y lo que hayas anotado. Ensayar es hacer mentalmente algo específico, como decir la primera frase. Enumerar los pasos es otra forma de prepararte. Ninguna de las dos equivale al intento real.","Una revisión encontró beneficios promedio de la simulación mental sobre la conducta, pero no estableció qué tipo era mejor. Tampoco demuestra que este ensayo breve funcione. Úsalo para detectar dónde te trabas y qué podrías hacer. Si no aparecen imágenes, descríbelo con palabras. Después escribe la siguiente frase útil de esa misma tarea."],practice:["Nombra un cambio que quieres que tu meta traiga a tu vida.","Ordena tus dos primeros pasos, con imágenes o palabras.","Después del ensayo, haz un paso concreto de preparación."],reflection:"¿Qué preparación pendiente descubriste al ensayar?",question:"¿Qué significa ensayar mentalmente en este curso?",options:["Un ejercicio para prepararte a actuar.","Controlar con certeza lo que ocurre afuera mediante tus pensamientos.","No tener que intentarlo nunca más."],correct:0,feedback:"Ensayar es prepararte. Los estudios citados no validan este ejercicio breve ni muestran que controle resultados externos. Usa la preparación para ayudarte a hacer algo concreto.",takeaway:"Termina la preparación haciendo algo concreto. Anota cada cosa por separado.",sources:["M04","M10"],deeper:[{heading:"Lo que permite comparar la investigación sobre simulación",paragraphs:["La revisión de Cole y sus colegas, de 2021, reunió 94 estudios, 123 efectos y 5,685 participantes. La simulación mental mostró un efecto general sobre la conducta de g = .49, con un intervalo de confianza del 95% entre .37 y .62. La mayoría de las muestras eran estudiantes. Las simulaciones variaban en contenido, cantidad y resultados. Ese promedio no predice lo que pasará en tu ejercicio breve. [M04]","La revisión distinguió pensar los pasos de un proceso de realizar mentalmente una tarea. La estimación para imaginar solo el proceso usó cinco efectos y su intervalo de confianza incluyó la ausencia de efecto. La comparación general entre tipos no fue estadísticamente significativa. Los promedios mayores de algunos subgrupos no establecen un ganador fiable. Una gráfica no te obliga a visualizar con más fuerza. Esta lección usa el ensayo para descubrir un detalle práctico y después pide intentar la tarea. Describirlo por escrito es una opción de accesibilidad; no afirma equivalencia con las imágenes demostrada por la investigación."]},{heading:"Prepárate para un momento y después aprovéchalo",paragraphs:["En el experimento original de planificación del informe, las personas imaginaron una hora y un lugar específicos para empezar. La comparación de puntualidad se refería a las personas identificables que entregaron el informe y a una tarea estudiantil concreta. No establece un guion universal para imaginar ni un beneficio de ensayar en la cama. [M10] Aquí, prepararte vale la pena cuando te ayuda a hacer la siguiente parte de la tarea que ya elegiste para tu meta.","Quizá descubras que falta una contraseña, hay una instrucción poco clara o todavía no sabes explicar una frase. Restablecer la contraseña es preparación; enviar la información necesaria es hacer la tarea. Refleja esa diferencia cuando anotes lo ocurrido. Si planear al acostarte te mantiene despierto, detente y elige un momento diurno. Es una adaptación práctica del curso. El ensayo breve es opcional, no un ritual validado ni un requisito para empezar. No necesitas imágenes vívidas ni sentirte de una forma particular."]}],example:{title:"Daniel enfrenta la línea en blanco",text:"Después de cenar, Daniel retoma su currículum. Durante treinta segundos ensaya cómo describir un cambio complicado de turnos. Cree que se quedará en blanco. Practica empezar con «Cambié ocho turnos cuando…». Después escribe una frase útil. Borra dos palabras y deja una pregunta para pedir comentarios. El ensayo no mostró cuánto detalle necesitaba."}},{id:"manifest-3",v2:n[2],photo:{id:"1767134063671-322e6faf9206",alt:"Árbol caído que bloquea un sendero de bosque frondoso"},schemaVersion:2,title:"El obstáculo existe. Cambia las condiciones",minutes:6,goal:"Usa tu último intento para elegir y probar qué puedes hacer ante un obstáculo.",reading:["Sigue con tu meta y revisa tus notas. ¿Aún no lo intentaste? Nombra una barrera probable. «No puedo usar la computadora después de cenar» orienta qué hacer. «Me falta disciplina» no identifica qué te frena.","Combinar un resultado deseado, un obstáculo real y un plan de «si pasa esto, haré aquello» mostró beneficios promedio modestos. Los estudios no establecieron que funcione por generar incomodidad. Dinero, cuidados, tiempo y acceso son condiciones, no fallas de tus creencias. Prueba un cambio: reducir la tarea, buscar un momento disponible o pedir apoyo específico. Pedir ayuda cuenta como pedirla, no como recibirla."],practice:["Identifica el obstáculo más cercano a tu meta.","Separa lo que puedes cambiar de lo que necesita apoyo o tiempo.","Si ahora no es posible, reduce la meta o elige un momento adecuado."],reflection:"Al mirar tu obstáculo con más realismo, ¿qué cambió en tu plan?",question:"Cuando las condiciones externas dificultan avanzar…",options:["Debo suponer que no creí lo suficiente.","Debo ignorar las condiciones.","Puedo revisar el apoyo, el horario o el tamaño de la meta."],correct:2,feedback:"Un plan realista considera las condiciones externas. Tus pensamientos no deciden por sí solos los resultados.",takeaway:"Identifica la condición que te frena. Cambia la tarea o pide el apoyo necesario.",sources:["M01","M11","M14"],deeper:[{heading:"El obstáculo informa; no hay que provocarlo",paragraphs:["La revisión de 2021 sobre contraste mental y planificación encontró una mejora promedio modesta para alcanzar metas, con 24 efectos independientes. La gran variación y las señales de sesgo de publicación limitan la certeza. No aisló la incomodidad como ingrediente activo. Nombrar una dificultad puede ser desagradable, pero el ejercicio no busca aumentar deliberadamente tu malestar. [M01]","En el procedimiento de Oettingen y sus colegas, de 2015, se pidió a estudiantes detallar un resultado deseado y un obstáculo principal. Después elegían una respuesta, armaban un plan ante ese obstáculo y añadían hora y lugar habituales. En el Estudio 1, la comparación prevista favoreció el método en horas agendadas. Se midió lo programado, no el trabajo terminado, y la prueba general entre condiciones no fue concluyente. [M11] ODA añade comprobar la viabilidad y hacer un intento. Ese experimento no validó por separado este ejercicio breve ni su distinción entre condiciones externas y respuestas personales."]},{heading:"Cuando lo adecuado es pedir apoyo",paragraphs:["Separa lo que quieres lograr de las condiciones que necesitas para buscarlo. Si falta una herramienta, necesitas acceso. Si hay peligro, protección. Si debes cuidar a alguien, quizá otro horario. Esta elección del curso se apoya en la investigación sobre planes; no pretende clasificar cada obstáculo en una sola categoría. Una petición es concreta cuando dice qué ayuda necesitas y para qué momento. [M01, M11]","Si alguien no ha contestado, anota la petición y que falta respuesta. No anotes ayuda recibida ni tarea terminada. Puedes elegir otro paso viable, revisar la meta o pausar. Ante malestar persistente o dificultades importantes para funcionar, busca apoyo profesional en lugar de intensificar el ejercicio. La guía del NIMH ofrece vías de atención y ayuda en crisis; no demuestra que ODA trate una condición. [M14] Tu próxima nota debe describir lo que elegiste hacer, incluida la protección o el apoyo, sin convertir el obstáculo inicial en una falta de fe en ti."]}],example:{title:"Daniel cambia de horario",text:"Daniel quería editar su currículum después de cenar, pero su hija necesitaba la computadora compartida para la tarea. Anota el conflicto. Pregunta si puede usarla diez minutos antes de cenar mañana. Acuerdan ese horario. Mejora una frase y se detiene. La solicitud todavía necesita trabajo."}},{id:"manifest-4",v2:n[3],photo:{id:"1591462391971-9ffc57b382b9",alt:"Notas adhesivas de colores y bolígrafos"},schemaVersion:2,title:"Deja de esperar a tener ganas",minutes:6,goal:"Elige una señal clara para empezar y un paso pequeño ante el punto que te trabó.",reading:["La señal para empezar y el plan ante un obstáculo cumplen funciones distintas. «Después de recoger los platos, escribiré una frase del currículum» fija un momento. «Si me trabo, describiré un cambio de turno» te ayuda durante la tarea.","Con distintas metas, los planes de «si pasa esto, haré aquello» favorecieron actuar, en promedio. No eliminan toda necesidad de recordar, esforzarte o resolver barreras prácticas. Mantén tu tarea y atiende un obstáculo anotado, si existe. Elige una señal clara y algo que puedas hacer cuando llegue. Si no ocurre, elige «No hubo ocasión» y busca otro momento."],practice:["Describe una señal del obstáculo empezando con «Si…».","Después de «entonces…», escribe una sola acción pequeña.","Comprueba que tienes tiempo y herramientas suficientes. Después ensaya el plan una vez."],reflection:"¿Cuál es tu frase de «si pasa esto, haré aquello»?",question:"¿Qué plan puedes probar de verdad?",options:["Todo se arreglará solo.","Si me trabo al abrir el archivo, primero escribiré el título.","Si envío buena energía, desaparecerán todos los obstáculos."],correct:1,feedback:"La segunda opción une una situación específica con una acción observable. Este tipo de plan se parece al enfoque estudiado en la investigación.",takeaway:"Decide cuándo empezar y qué hacer si te trabas. Luego comprueba qué ocurrió.",sources:["M02","M10","M11"],deeper:[{heading:"Qué aporta un plan específico",paragraphs:["El capítulo de Gollwitzer y Sheeran, de 2006, reunió 94 pruebas independientes con 8,461 participantes. Los planes de «si pasa esto, haré aquello» mostraron un efecto promedio para alcanzar metas de d = .65, con un intervalo de confianza del 95% entre .60 y .70. Variaban las tareas y los procedimientos. Esta evidencia antigua no contó siempre con registro previo. No establece que cualquier frase que escribas vaya a funcionar. [M02]","El experimento de planificación pidió elegir hora y lugar específicos para empezar un informe. Su comparación de puntualidad se refería a las personas identificables que entregaron el informe, no a todas las personas asignadas a la tarea. [M10] La enseñanza práctica es más limitada que «un plan reemplaza la fuerza de voluntad». Decide qué harás y después comprueba si ocurrió la situación, si la reconociste y si el paso era adecuado. Conserva recordatorios externos si los necesitas. Una nota junto a una herramienta es una opción de ODA, no una garantía probada de que la verás."]},{heading:"Dos funciones en un mismo intento",paragraphs:["El horario elegido responde cuándo intentarás la tarea. Tu plan ante el obstáculo responde qué harás si aparece una dificultad observada. El procedimiento de contraste mental estudiado vinculaba un obstáculo con una respuesta y añadía hora y lugar habituales. No estableció que todas las personas necesiten dos reglas separadas. [M11] El curso distingue sus funciones para ayudarte a entender mejor lo que pasó en tu intento.","Supón que nunca llega el momento previsto. No hay razón para decir que falló el plan ante el obstáculo. Si llega y no lo reconoces, cambia la señal o el recordatorio. Si lo reconoces, pero el paso es demasiado grande, reduce el siguiente paso de la tarea. Son opciones que puedes probar, no hallazgos demostrados por un registro personal. Mantén las notas anteriores ligadas al mínimo original. Cambiar el próximo plan no convierte un intento anterior incompleto en trabajo terminado. Revisa lo que hiciste. Puedes pedir apoyo, descansar, pausar o cambiar de meta."]}],example:{title:"Daniel aprovecha la señal",text:"Daniel deja una nota junto a la computadora compartida: «Al recoger los platos, mejorar una frase. Si me trabo, describir un cambio de turno». El jueves reconoce el momento y ve la nota. Escribe una frase útil, pero no termina la sección antes de retomar sus responsabilidades familiares. Anota ambas cosas."}},{id:"manifest-5",v2:n[4],photo:{id:"1762920738995-f393efe82205",alt:"Señal de madera con flechas en varias direcciones dentro de un bosque"},schemaVersion:2,title:"¿Sin resultados? Mira lo que hiciste",minutes:6,goal:"Usa tus registros para elegir un siguiente paso viable y cuándo revisarás la próxima semana.",reading:["Lee las notas de tu meta. Distingue lo planeado, ensayado y hecho de las respuestas de otras personas. Un borrador guardado demuestra que trabajaste. No demuestra que enviaste la solicitud ni que un empleador tenga interés.","Una revisión de 138 experimentos encontró beneficios promedio al aumentar el seguimiento del progreso. No validó este registro ni un calendario ideal de revisión. Elige según los hechos: repetir un paso viable, cambiar un problema, pedir comentarios o dejar una meta inadecuada. Si aún no lo intentaste, reconócelo y haz un primer avance concreto."],practice:["Haz tu primer intento pequeño o fija exactamente cuándo lo harás.","Elige una fecha razonable para revisar el resultado. Pregúntate: «¿Qué intenté? ¿Qué aprendí?».","Elige lo que te convenga: continuar, reducir el paso, pedir apoyo o cambiar la meta."],reflection:"¿Qué día revisarás tu plan y qué información mirarás?",question:"Si no llega el resultado que querías, ¿qué revisión sería más útil?",options:["Mis pensamientos no tuvieron suficiente fuerza.","Mirar lo que intenté y las condiciones para elegir el siguiente paso.","Mantener la misma expectativa sin mirar lo ocurrido."],correct:1,feedback:"Comparar el plan con los hechos aporta información. Ningún curso garantiza resultados. Puedes considerar tanto lo que hiciste como las condiciones externas.",takeaway:"Lo ocurrido orienta tu siguiente paso. Esfuerzo, preparación y resultados externos aportan información distinta.",sources:["M03","M01"],deeper:[{heading:"Observar el progreso ayuda a decidir",paragraphs:["La revisión de Harkin y sus colegas, de 2016, incluyó 138 experimentos con asignación aleatoria y 19,951 participantes en total. El análisis de logro de metas usó 18,398 participantes y encontró d = .40, con un intervalo de confianza del 95% entre .32 y .48. Un ajuste de sensibilidad por estudios pequeños dio una estimación menor. Variaban las intervenciones, metas y formas de registro. La revisión no probó el resumen de ODA ni su tarjeta del día siguiente. [M03]","Entre estudios, los efectos mayores se asociaron con anotar o informar públicamente el progreso. Esas comparaciones no establecen que compartirlo sea necesario ni que un formato de aplicación cause beneficios. Mantén tus detalles en privado si te conviene. Usa tus notas para comparar lo que pedía el plan con lo que dijiste haber hecho. Sin registro, lo ocurrido queda sin confirmar. Una preparación terminada, una petición sin respuesta o un intento detenido deben conservar su nombre. Así puedes revisar tu siguiente decisión sin exigir una historia positiva."]},{heading:"Elige la próxima semana sin reescribir esta",paragraphs:["Un registro personal breve puede sugerir un patrón, pero no demuestra por qué ocurrió un resultado externo. Solicitudes, pedidos y respuestas ajenas pueden depender de calidad, horario, recursos o circunstancias que tus notas no miden. La investigación respalda usar información; no establece cuántos intentos deben hacerse antes de cambiar una meta. [M03] Al revisar, conserva esa incertidumbre. No atribuyas a un solo paso más de lo que sabes.","Elige un próximo momento viable y cuándo revisarás la semana que viene. Conserva tu mínimo útil y lo que facilitó el acceso. Cambia la parte que tus notas ponen en duda. Si no hay intentos anotados, cuenta los hechos conocidos o toma la siguiente acción pequeña como tu primera prueba. No inventes un historial de esfuerzo. Los estudios de planificación muestran beneficios promedio variables, sin garantizar resultados. [M01] Pausar, pedir comentarios, buscar apoyo práctico o elegir otro rumbo pueden ser decisiones deliberadas de la revisión. Conserva la nota anterior para que siga claro por qué cambiaste."]}],example:{title:"Daniel planea la próxima semana",text:"Daniel lee tres cambios que anotó con fecha y una ocasión en que no pudo usar la computadora. Su currículum es más claro, pero no ha enviado ninguna solicitud. Elige una vacante adecuada, revisa los requisitos y envía la versión preparada el viernes. Anota el envío y programa una revisión para la próxima semana. Todavía no hay respuesta."}},...i.map(c)],lang:"es"},g=Object.freeze(Object.defineProperty({__proto__:null,COURSE:m,MANIFEST_LESSONS_V2:n,SOURCES:p},Symbol.toStringTag,{value:"Module"}));export{g as m};
